        /// **A request framed at a version this build does not cover is refused
        /// rather than understood**, which is the check
        /// `Server protocol and transfers` P3a leaves to the answering side.
        #[test]
        fn a_request_at_a_version_this_build_does_not_cover_is_refused() {
            let mut machine = nothing_written_yet();
            let from_the_future = Request::speaking(
                smoozy_framing::framing::ProtocolVersion(
                    THE_PROTOCOL_VERSION_THIS_BUILD_SPEAKS.0 + 6,
                ),
                Identity::issue(IdentityKind::Operation).expect("randomness"),
                THE_HEALTH_ANSWER_REQUEST,
            );
            let answered = answer(&from_the_future, &mut machine.start);
            assert_eq!(
                answered.the_protocol_version_it_says_it_does_not_speak(),
                Some(from_the_future.protocol_version)
            );
            // **The version is refused before the name is read**, so a request
            // this build cannot frame is not also reported as a name it does
            // not answer.
            assert_eq!(answered.the_request_name_it_says_it_does_not_answer(), None);
            assert!(
                answered.answers(&from_the_future),
                "`Server protocol and transfers` C2"
            );
        }

