        /// A machine that holds an installation identity and a phase record, so
        /// G12's four things can be answered and V9's fifth can ride with them.
        fn a_machine_a_placement_wrote() -> AStartOverAnAreaThatGoesWithIt {
            let mut machine = nothing_written_yet();
            readings_that_answer(&machine);
            let installation = Identity::issue(IdentityKind::Installation).expect("randomness");
            std::fs::write(machine.at.join("installation"), installation.as_text())
                .expect("the identity is written");
            let record = smoozy_runtime::package::phase::a_fresh_attempts_first_write(
                Identity::issue(IdentityKind::Operation).expect("randomness"),
                smoozy_runtime::package::release::VerifiedReleaseDescriptor {
                    manifest_format: "1".to_string(),
                    verified_release_sequence: 1,
                    requested_package_version: THE_PACKAGE_VERSION.to_string(),
                    manifest_digest: [0; 32],
                    artifact_identity: "smoozy-server".to_string(),
                    artifact_byte_length: 0,
                    artifact_digest: [0; 32],
                },
                None,
                smoozy_runtime::machine_kind::MachineKind::Systemd,
                machine.at.join("staged").display().to_string(),
            );
            std::fs::write(
                machine.at.join("package-phase"),
                smoozy_runtime::written_form::write(&record).expect("it writes"),
            )
            .expect("the phase record is written");
            machine.start.the_machines_own_clock =
                Some(Clock::AMachine(MachineClock(installation.as_text())));
            machine
        }

        /// **V9: the setup-in-progress state and its run's identity are reported
        /// with every health answer**, and the field is absent where no setup is
        /// in progress.
        #[test]
        fn the_health_answer_reports_the_setup_in_progress_state_and_its_run() {
            let mut machine = a_machine_a_placement_wrote();
            let request = a_request(THE_HEALTH_ANSWER_REQUEST);
            let before = answer(&request, &mut machine.start);
            assert_eq!(
                before
                    .fields
                    .text(smoozy_runtime::acting::readings::THE_SETUP_IN_PROGRESS_FIELD),
                None,
                "no setup is in progress and the field says nothing rather than something"
            );

            let run = Identity::issue(IdentityKind::Operation).expect("randomness");
            machine.start.setup_state.set(&run).expect("P4's write");
            let after = answer(&request, &mut machine.start);
            assert_eq!(
                after
                    .fields
                    .text(smoozy_runtime::acting::readings::THE_SETUP_IN_PROGRESS_FIELD),
                Some(run.as_text().as_str())
            );
            // **And the four are still the four**, which is what V9 rides
            // beside rather than joins.
            assert_eq!(
                after.fields.text("package version"),
                Some(THE_PACKAGE_VERSION)
            );
        }

        /// **P3's two acts, through the command path**, and P8's refusal between
        /// them.
        #[test]
        fn the_setup_state_is_set_and_cleared_through_the_command_path() {
            let mut machine = a_machine_a_placement_wrote();
            let run = Identity::issue(IdentityKind::Operation).expect("randomness");
            let set = Request::speaking(
                THE_PROTOCOL_VERSION_THIS_BUILD_SPEAKS,
                Identity::issue(IdentityKind::Operation).expect("randomness"),
                THE_SETUP_IN_PROGRESS_IS_SET_REQUEST,
            )
            .carrying(Fields::none().and(THE_SETUP_RUN_FIELD, run.as_text()));
            let answered = answer(&set, &mut machine.start);
            assert_eq!(
                answered.fields.text(THE_SETUP_RUN_FIELD),
                Some(run.as_text().as_str())
            );
            assert!(machine
                .start
                .setup_state
                .read()
                .expect("it reads")
                .is_some());

            // **P8: another run finds the state and does not clear it**, and it
            // is told which run stands in its way.
            let another = Identity::issue(IdentityKind::Operation).expect("randomness");
            let refused = answer(
                &Request::speaking(
                    THE_PROTOCOL_VERSION_THIS_BUILD_SPEAKS,
                    Identity::issue(IdentityKind::Operation).expect("randomness"),
                    THE_SETUP_IN_PROGRESS_IS_CLEARED_REQUEST,
                )
                .carrying(Fields::none().and(THE_SETUP_RUN_FIELD, another.as_text())),
                &mut machine.start,
            );
            assert_eq!(
                refused.fields.text(THE_SETUP_RUN_FIELD),
                Some(run.as_text().as_str())
            );
            assert!(machine
                .start
                .setup_state
                .read()
                .expect("it reads")
                .is_some());

            // **P5: the run that set it clears it.**
            let cleared = answer(
                &Request::speaking(
                    THE_PROTOCOL_VERSION_THIS_BUILD_SPEAKS,
                    Identity::issue(IdentityKind::Operation).expect("randomness"),
                    THE_SETUP_IN_PROGRESS_IS_CLEARED_REQUEST,
                )
                .carrying(Fields::none().and(THE_SETUP_RUN_FIELD, run.as_text())),
                &mut machine.start,
            );
            // **The clear's success carries a field of its own**, so a blank
            // result means trouble everywhere in this dispatch.
            assert_eq!(
                cleared.fields.text(THE_SETUP_RUN_THE_CLEAR_REMOVED_FIELD),
                Some(run.as_text().as_str())
            );
            assert!(machine
                .start
                .setup_state
                .read()
                .expect("it reads")
                .is_none());
        }

        /// **A request naming no run is a request this package does not answer**,
        /// rather than one answered on a value made up here.
        #[test]
        fn a_setup_state_request_naming_no_run_is_refused_by_name() {
            let mut machine = a_machine_a_placement_wrote();
            for name in [
                THE_SETUP_IN_PROGRESS_IS_SET_REQUEST,
                THE_SETUP_IN_PROGRESS_IS_CLEARED_REQUEST,
            ] {
                let answered = answer(&a_request(name), &mut machine.start);
                assert_eq!(
                    answered.the_request_name_it_says_it_does_not_answer(),
                    Some(name)
                );
            }
        }

        /// One hold record, placed the way U1's first origin places one.
        fn a_hold_is_placed(machine: &AStartOverAnAreaThatGoesWithIt) -> Identity {
            let hold = Identity::issue(IdentityKind::Operation).expect("randomness");
            machine
                .start
                .holds
                .place(&smoozy_runtime::holds::HoldRecord {
                    hold: hold.clone(),
                    subject: smoozy_runtime::holds::Subject::Job(
                        Identity::issue(IdentityKind::Job).expect("randomness"),
                    ),
                    reason: "the first-frame check".to_string(),
                    origin: smoozy_runtime::holds::Origin::Submission,
                    dependency: None,
                    release: None,
                })
                .expect("the hold is placed");
            hold
        }

        fn an_answer_to(hold: &Identity, says: &str, route: &str) -> Request {
            Request::speaking(
                THE_PROTOCOL_VERSION_THIS_BUILD_SPEAKS,
                Identity::issue(IdentityKind::Operation).expect("randomness"),
                THE_ANSWER_TO_A_HOLD_REQUEST,
            )
            .carrying(
                Fields::none()
                    .and(THE_HOLD_FIELD, hold.as_text())
                    .and(THE_ANSWER_FIELD, says)
                    .and(THE_ROUTE_FIELD, route),
            )
        }

        /// **U12: the supervisor applies the answer by writing the release
        /// outcome, once, and the write is what releases the subject.**
        ///
        /// **U26: the release is journalled when it is written**, so a reader
        /// learns of it by reading forward rather than by comparing two readings.
        #[test]
        fn a_yes_writes_the_release_outcome_once_and_journals_it() {
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            let before = machine.start.journal.next_sequence();

            let request = an_answer_to(&hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK);
            let answered = answer(&request, &mut machine.start);
            assert_eq!(
                answered.fields.text(THE_RELEASE_OUTCOME_FIELD),
                Some("released")
            );
            assert!(
                answered.answers(&request),
                "`Server protocol and transfers` C2"
            );
            let written = machine
                .start
                .holds
                .read(&hold)
                .expect("it reads")
                .expect("the record is there")
                .release
                .expect("U12's single write landed");
            assert_eq!(
                written.outcome,
                smoozy_runtime::holds::ReleaseOutcome::Released
            );
            assert_eq!(
                machine.start.journal.next_sequence(),
                before + 1,
                "U26: the release is journalled when it is written"
            );
        }

        /// **A release event says which hold it is about, and which answer was
        /// applied.**
        ///
        /// **It carried the kind, a number, a moment, and the same sentence
        /// again until 2026-09-12**, so a reader learnt that something had been
        /// released and could not tell the user which job. `State, identity and
        /// recovery` E2's *about* field is how a reader finds its own work, and
        /// the same file already used that field correctly for reconciliation.
        #[test]
        fn a_release_event_says_which_hold_it_is_about_and_which_answer_was_applied() {
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            let before = machine.start.journal.next_sequence();

            answer(
                &an_answer_to(&hold, THE_ANSWER_IS_NO, THE_ROUTE_IS_THE_PHONE),
                &mut machine.start,
            );

            let read = machine
                .start
                .journal
                .read_forward_from(before, 10)
                .expect("the journal reads");
            let event = read.events.last().expect("the release was journalled");
            assert_eq!(event.what().kind, THE_RELEASE_EVENT);
            assert_eq!(
                event.what().about.as_ref(),
                Some(&hold),
                "`State, identity and recovery` E2: the event is about the hold, so a reader \
                 can tell which job"
            );
            assert!(
                event.what().says.contains("stopped"),
                "the answer that was applied is in the words: {}",
                event.what().says
            );
        }

        /// **A release the store refuses is held pending and lands at the next
        /// request, and the caller is told it is still in hand.**
        ///
        /// **S14: a durable write refused for want of room is held and
        /// re-attempted until it lands.** Until 2026-09-12 it was dropped, and
        /// what that cost is exact: this run has already recorded the answer, and
        /// `Server protocol and transfers` C4 says a request repeating a recorded
        /// identity never acts again — so the person who pressed *yes* would have
        /// waited for ever.
        ///
        /// The refusal is posed by taking the hold store's area away and putting
        /// it back, which is the shape of a mount that filled and then had room
        /// again.
        #[test]
        fn a_release_the_store_refused_is_held_pending_and_lands_at_the_next_request() {
            use std::os::unix::fs::PermissionsExt;
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            let area = machine
                .at
                .join(smoozy_runtime::the_program::records::THE_AREA_THE_HOLD_RECORDS_SIT_IN);
            // **The record still reads and the write is refused**, which is the
            // shape of a mount with no room: the area takes no new entry while
            // everything in it is still there to be read.
            let as_it_was = std::fs::metadata(&area)
                .expect("the area is there")
                .permissions();
            let mut closed = as_it_was.clone();
            closed.set_mode(0o555);
            std::fs::set_permissions(&area, closed).expect("the area is closed to new entries");

            let answered = answer(
                &an_answer_to(&hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK),
                &mut machine.start,
            );
            assert_eq!(
                answered.fields.text(WHAT_BECAME_OF_THE_ANSWER_FIELD),
                Some(THE_ANSWER_IS_STILL_IN_HAND),
                "C8: the identity is recorded and has no outcome yet"
            );
            assert_eq!(machine.start.pending.owed().len(), 1, "S14: it is held");

            // Room comes back, and the next request the supervisor serves is
            // S14's own first occasion.
            std::fs::set_permissions(&area, as_it_was).expect("the area takes entries again");
            let before = machine.start.journal.next_sequence();
            answer(&a_request(THE_READINESS_REQUEST), &mut machine.start);

            assert!(machine.start.pending.owed().is_empty(), "it landed");
            assert_eq!(
                machine
                    .start
                    .holds
                    .read(&hold)
                    .expect("it reads")
                    .expect("the record is there")
                    .release
                    .expect("U12's write landed at the re-attempt")
                    .outcome,
                smoozy_runtime::holds::ReleaseOutcome::Released
            );
            let read = machine
                .start
                .journal
                .read_forward_from(before, 10)
                .expect("the journal reads");
            let event = read.events.last().expect("U26's event rides the landing");
            assert_eq!(event.what().kind, THE_RELEASE_EVENT);
            assert_eq!(event.what().about.as_ref(), Some(&hold));
        }

        /// **U15: a *no* is not converted into a stop**, and **U13 and U14: the
        /// first answer recorded wins and the one that lost is told what happened
        /// rather than that it failed.**
        #[test]
        fn a_no_after_a_yes_is_told_which_answer_was_applied_and_changes_nothing() {
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            answer(
                &an_answer_to(&hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK),
                &mut machine.start,
            );

            let late = an_answer_to(&hold, THE_ANSWER_IS_NO, THE_ROUTE_IS_THE_PHONE);
            let answered = answer(&late, &mut machine.start);
            assert_eq!(
                answered.fields.text(THE_RELEASE_OUTCOME_FIELD),
                Some("released"),
                "U14: it is told which answer was applied"
            );
            assert_eq!(
                machine
                    .start
                    .holds
                    .read(&hold)
                    .expect("it reads")
                    .expect("the record is there")
                    .release
                    .expect("still the first answer's")
                    .outcome,
                smoozy_runtime::holds::ReleaseOutcome::Released,
                "U16: the order is whatever the machine recorded"
            );
        }

        /// **`Rented-server runtime` U12a: a *no* that finds the release already
        /// *stopped* and its job still held removes the job** — the shape an
        /// older program's *no* left on a machine, and the shape a removal the
        /// store refused leaves. **A *yes* that meets it removes nothing** and
        /// is told what stood (`Rented-server runtime` U14). Step 10c's
        /// eleventh-pass fix piece 8b.
        #[test]
        fn a_no_that_finds_stopped_and_its_job_still_held_removes_the_job() {
            let mut machine = a_machine_a_placement_wrote();
            let job = Identity::issue(IdentityKind::Job).expect("randomness");
            let hold = Identity::issue(IdentityKind::Operation).expect("randomness");
            machine
                .start
                .queue
                .write(&JobRecord::held_from_submission(
                    job.clone(),
                    None,
                    "/r".to_string(),
                    hold.clone(),
                ))
                .expect("written");
            machine
                .start
                .holds
                .place(&smoozy_runtime::holds::HoldRecord {
                    hold: hold.clone(),
                    subject: smoozy_runtime::holds::Subject::Job(job.clone()),
                    reason: "the first-frame check".to_string(),
                    origin: smoozy_runtime::holds::Origin::Submission,
                    dependency: None,
                    release: Some(Release {
                        outcome: smoozy_runtime::holds::ReleaseOutcome::Stopped,
                        produced_by: "the answer".to_string(),
                        at: Reading::taken(
                            (),
                            std::time::SystemTime::now(),
                            Clock::AMachine(MachineClock("an older program's".to_string())),
                        ),
                    }),
                })
                .expect("the hold is placed");

            let yes = answer(
                &an_answer_to(&hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK),
                &mut machine.start,
            );
            assert_eq!(yes.fields.text(THE_RELEASE_OUTCOME_FIELD), Some("stopped"));
            assert_eq!(
                yes.fields.text(asked::THE_CANCELS_OUTCOME_FIELD),
                None,
                "a yes removes nothing"
            );
            assert!(machine
                .start
                .queue
                .read_one(&job)
                .expect("it reads")
                .is_some());

            let no = answer(
                &an_answer_to(&hold, THE_ANSWER_IS_NO, THE_ROUTE_IS_THE_PHONE),
                &mut machine.start,
            );
            assert_eq!(no.fields.text(THE_RELEASE_OUTCOME_FIELD), Some("stopped"));
            assert_eq!(
                no.fields.text(asked::THE_CANCELS_OUTCOME_FIELD),
                Some(asked::IT_WAS_REMOVED)
            );
            assert_eq!(
                machine.start.queue.read_one(&job),
                Ok(None),
                "the job is gone"
            );
            assert_eq!(
                machine.start.holds.read(&hold),
                Ok(None),
                "and its hold with it"
            );
        }

        /// **A *no* on its own writes *stopped*.**
        #[test]
        fn a_no_writes_stopped_as_the_release_outcome() {
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            let answered = answer(
                &an_answer_to(&hold, THE_ANSWER_IS_NO, THE_ROUTE_IS_THE_PHONE),
                &mut machine.start,
            );
            assert_eq!(
                answered.fields.text(THE_RELEASE_OUTCOME_FIELD),
                Some("stopped")
            );
        }

        /// **`Server protocol and transfers` C4: a request repeating an identity
        /// already recorded never acts again**, and the outcome is not rewritten.
        #[test]
        fn an_answer_repeating_its_own_identity_does_not_act_a_second_time() {
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            let request = an_answer_to(&hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK);
            answer(&request, &mut machine.start);
            let placed_at = machine
                .start
                .holds
                .read(&hold)
                .expect("it reads")
                .expect("the record is there")
                .release
                .expect("it landed")
                .at
                .taken_at();

            let again = answer(&request, &mut machine.start);
            assert_eq!(
                again.fields.text(THE_RELEASE_OUTCOME_FIELD),
                Some("released")
            );
            assert_eq!(
                machine
                    .start
                    .holds
                    .read(&hold)
                    .expect("it reads")
                    .expect("the record is there")
                    .release
                    .expect("it is there")
                    .at
                    .taken_at(),
                placed_at,
                "the outcome was not rewritten"
            );
        }

        /// **A hold nothing placed is not answered on a made-up record, and the
        /// caller is told which of C8's three that is.**
        ///
        /// **It carried nothing at all until 2026-09-12**, which is the same
        /// blank result a store that refused also gave and a fine answer gave
        /// too. The command was recorded and its act wrote no outcome, so what
        /// the machine can say about it is *still in hand*.
        #[test]
        fn an_answer_to_a_hold_that_is_not_there_says_still_in_hand_rather_than_nothing() {
            let mut machine = a_machine_a_placement_wrote();
            let nowhere = Identity::issue(IdentityKind::Operation).expect("randomness");
            let answered = answer(
                &an_answer_to(&nowhere, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK),
                &mut machine.start,
            );
            assert_eq!(
                answered.fields.text(WHAT_BECAME_OF_THE_ANSWER_FIELD),
                Some(THE_ANSWER_IS_STILL_IN_HAND)
            );
            assert_eq!(
                answered.fields.text(THE_RELEASE_OUTCOME_FIELD),
                None,
                "nothing was applied, so nothing is reported as applied"
            );
        }

        /// **An answer missing a part this command needs, or naming a value it
        /// does not know, is refused by name** rather than answered on a value
        /// composed here.
        #[test]
        fn an_answer_missing_one_of_its_three_parts_is_refused_by_name() {
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            for fields in [
                Fields::none().and(THE_ANSWER_FIELD, THE_ANSWER_IS_YES),
                Fields::none().and(THE_HOLD_FIELD, hold.as_text()),
                Fields::none()
                    .and(THE_HOLD_FIELD, hold.as_text())
                    .and(THE_ANSWER_FIELD, "perhaps")
                    .and(THE_ROUTE_FIELD, THE_ROUTE_IS_THE_DESK),
                Fields::none()
                    .and(THE_HOLD_FIELD, hold.as_text())
                    .and(THE_ANSWER_FIELD, THE_ANSWER_IS_YES)
                    .and(THE_ROUTE_FIELD, "a third route"),
            ] {
                let request = Request::speaking(
                    THE_PROTOCOL_VERSION_THIS_BUILD_SPEAKS,
                    Identity::issue(IdentityKind::Operation).expect("randomness"),
                    THE_ANSWER_TO_A_HOLD_REQUEST,
                )
                .carrying(fields);
                let answered = answer(&request, &mut machine.start);
                assert_eq!(
                    answered.the_request_name_it_says_it_does_not_answer(),
                    Some(THE_ANSWER_TO_A_HOLD_REQUEST)
                );
            }
        }

        /// **U14, whole: the result carries which answer was applied AND the
        /// moment on the machine's clock**, and the moment is the one on the
        /// record rather than a second reading taken here.
        #[test]
        fn the_result_carries_the_moment_on_the_machines_clock_as_well_as_the_outcome() {
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            let request = an_answer_to(&hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK);
            let answered = answer(&request, &mut machine.start);

            let on_the_record = machine
                .start
                .holds
                .read(&hold)
                .expect("it reads")
                .expect("the record is there")
                .release
                .expect("U12's write landed");
            assert_eq!(
                answered.fields.text(THE_RELEASE_MOMENT_FIELD),
                Some(the_release_moment_as_text(&on_the_record.at).as_str()),
                "U14: the moment on the machine's clock, and the record's own"
            );
        }

        /// **`Server protocol and transfers` C4, proved rather than argued: a
        /// store that refuses leaves the hold's release unwritten.**
        ///
        /// **The record is written durably before the act**, so a machine whose
        /// record store refuses — a full disk, a mount gone read-only, whatever
        /// the store said — must not release the hold, because the release is
        /// the deciding write and it is what puts a job in the line.
        ///
        /// The refusal is posed by taking the record store's area away under
        /// it, which is the shape of every real one: the store's own words come
        /// back and are not *already recorded*.
        #[test]
        fn a_record_store_that_refuses_leaves_the_holds_release_unwritten() {
            let mut machine = a_machine_a_placement_wrote();
            let hold = a_hold_is_placed(&machine);
            std::fs::remove_dir_all(machine.at.join(THE_AREA_THE_TWO_RECORDS_SIT_IN))
                .expect("the record store's area is taken away");

            let request = an_answer_to(&hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK);
            let answered = answer(&request, &mut machine.start);
            assert_eq!(
                answered.fields.text(THE_RELEASE_OUTCOME_FIELD),
                None,
                "nothing was applied, so nothing is reported as applied"
            );
            // **C8's third, in its own words**: it arrived and was refused
            // before it was recorded, and the work did not happen. **This came
            // back blank until 2026-09-12** — the same result a fine answer came
            // back as.
            assert_eq!(
                answered.fields.text(WHAT_BECAME_OF_THE_ANSWER_FIELD),
                Some(THERE_IS_NO_RECORD_OF_THAT_ANSWER)
            );
            assert_eq!(
                machine
                    .start
                    .holds
                    .read(&hold)
                    .expect("it reads")
                    .expect("the record is there")
                    .release,
                None,
                "C4: the release is the deciding write and it did not happen"
            );
        }

        // --- W8's two acts on the role's desired state ---

        fn a_role_request(name: &str) -> Request {
            Request::speaking(
                THE_PROTOCOL_VERSION_THIS_BUILD_SPEAKS,
                Identity::issue(IdentityKind::Operation).expect("randomness"),
                name,
            )
        }

        /// **A real program at the active-package pointer**, because G7 makes a
        /// worker's invocation the pointer's own path and a start with nothing
        /// there starts nothing.
        ///
        /// **It is not this program**: a bin target's own tests cannot name
        /// their binary, and what is being proved here is the supervisor's side
        /// of the start rather than what a Telegram worker does. **The real
        /// binary is driven through the package area in
        /// `tests/the_program_runs.rs`**, which is where the whole path is run
        /// end to end.
        ///
        /// # It stays up, and that is the whole point of it
        ///
        /// **It exited at once until 2026-09-12, and that is what failed on
        /// Linux in run `34697517090`.** A worker that exits the instant it is
        /// started is not a role worker: W7's worker runs for as long as the
        /// role is enabled, and `Telegram` section 19's termination is a signal
        /// to a process that is still there to receive one. With a stand-in that
        /// had already ended, the supervisor's wait took its ending on the very
        /// pass the disable arrived on, the standing worker was cleared with it,
        /// and there was correctly nothing left to signal — **so the test asked
        /// for a signal on a machine where no worker was running.** The desk
        /// never saw it, because the desk composed no pair until 2026-10-24
        /// and took the other limb whatever the stand-in did.
        ///
        /// **The wait is bounded rather than endless** so that nothing outlives
        /// the test by more than a few seconds on a desk that never signals it,
        /// and `exec` is what makes the recorded pair the waiting process's own
        /// rather than a shell's around it.
        fn a_program_at_the_pointer(machine: &AStartOverAnAreaThatGoesWithIt) {
            use std::os::unix::fs::PermissionsExt;
            let at = machine
                .at
                .join(smoozy_runtime::the_program::THE_FIXED_ENTRY_POINT_NAME);
            std::fs::write(&at, "#!/bin/sh\nexec sleep 10\n").expect("the program is written");
            std::fs::set_permissions(&at, std::fs::Permissions::from_mode(0o755))
                .expect("it is made runnable");
        }

        /// Whether the kernel of the machine this test runs on answers for a
        /// process, through the reader this program itself uses.
        ///
        /// **Every rented machine does, and the desk does too since
        /// 2026-10-24** (step 12's piece SC0b). Where it does not, the start
        /// answers with the honest half — a real child ran, it is in the wait,
        /// and no pair was invented — exactly as `smoozy_runtime`'s own tests
        /// of the same unit split.
        fn the_kernel_here_publishes_records() -> bool {
            matches!(
                smoozy_runtime::execution_group::ValidatesTheRecordedPair::what_is_at(
                    &smoozy_runtime::acting::execution_group::ThePairAsTheKernelReportsIt::the_rented_machine(),
                    std::process::id(),
                ),
                Ok(Some(_))
            )
        }

        /// **W8: `Server Setup` sets the role's desired state through the
        /// ordinary command path, and the supervisor does the rest.**
        ///
        /// **W7: the state is durable**, so it is read back off the disk here
        /// rather than out of the value that wrote it. **W10: enabling starts
        /// the role worker**, which is a real child of this program in its
        /// Telegram worker mode; **disabling never resurrects it.**
        #[test]
        fn the_roles_desired_state_is_written_through_the_command_path_and_the_worker_follows_it() {
            let mut machine = a_machine_a_placement_wrote();
            a_program_at_the_pointer(&machine);
            assert_eq!(
                machine.start.role_state.read().expect("it reads"),
                RoleDesiredState::Disabled,
                "W7: a machine nothing has written it on holds no role"
            );

            let enabled = answer(
                &a_role_request(THE_TELEGRAM_ROLE_IS_ENABLED_REQUEST),
                &mut machine.start,
            );
            assert_eq!(
                machine.start.role_state.read().expect("it reads"),
                RoleDesiredState::Enabled,
                "W8's durable write"
            );
            let said = enabled
                .fields
                .text(WHAT_THE_ROLE_WORKER_DID_FIELD)
                .expect("the caller is told what happened to the worker");
            if the_kernel_here_publishes_records() {
                assert!(
                    said.starts_with("started"),
                    "W10: the supervisor starts it while the state is enabled — {said}"
                );
            } else {
                assert!(
                    said.contains("the kernel recorded nothing for it"),
                    "this kernel records nothing, so no pair can be composed — {said}"
                );
            }
            assert_eq!(
                machine.start.wait.how_many_it_holds(),
                1,
                "X9a: a real child was started and this supervisor is waiting on it"
            );

            let disabled = answer(
                &a_role_request(THE_TELEGRAM_ROLE_IS_DISABLED_REQUEST),
                &mut machine.start,
            );
            assert_eq!(
                machine.start.role_state.read().expect("it reads"),
                RoleDesiredState::Disabled
            );
            let said = disabled
                .fields
                .text(WHAT_THE_ROLE_WORKER_DID_FIELD)
                .expect("the caller is told what happened to the worker");
            if the_kernel_here_publishes_records() {
                // **`Telegram` section 19: the polite signal to the worker's own
                // process.** It said *nothing was started* until 2026-09-12 and
                // signalled nothing, so a user who switched Telegram off went on
                // getting messages on their phone.
                //
                // **And it said *no worker of this run is running* on Linux in
                // run `34697517090`**, because the stand-in above exited the
                // instant it was started and the wait took its ending on this
                // very pass. The supervisor was right to signal nothing; what
                // was wrong was asking a worker that was already over to be
                // stopped. The stand-in stays up now, so what is posed here is
                // the case the clause is about.
                assert!(
                    said.starts_with("the role is disabled and the worker was signalled"),
                    "W10 and `Telegram` section 19: turning it off stops the bot — {said}"
                );
            } else {
                // No pair was composed, so this supervisor holds no group
                // to signal and says so rather than reaching for a bare
                // identifier. **It said *no worker of this run is running*
                // until 2026-10-16**, which was not true: the worker was
                // running, and was simply not held — the Telegram worker's
                // map, §6 item 2. It is held now, by the wait's own key.
                assert!(
                    said.contains("was not signalled: no pair was taken"),
                    "{said}"
                );
            }
            assert_eq!(
                machine.start.wait.how_many_it_holds(),
                1,
                "W10: the supervisor still waits on the worker it started, and the ending is \
                 taken from the wait rather than inferred from the signal"
            );
        }

        /// **The disable says which of the two silences it met** — added
        /// 2026-09-12, out of the Linux failure of run `34697517090`.
        ///
        /// *Nothing was ever started under this run* and *what was started has
        /// already ended* answered with one sentence, and the run that failed
        /// was the second of them — which nobody reading its log could tell from
        /// the first. **The act is unchanged and stays unchanged**: X8 step 3
        /// sends nothing to a group that has ended, whichever of the two it was.
        ///
        /// **This is the half of the disable that needs no pair.** The
        /// signalled half wants X1's pair, and is the test above this one's
        /// (run at the desk too since 2026-10-24, step 12's piece SC0b).
        #[test]
        fn the_disable_tells_a_worker_that_has_ended_from_one_that_never_ran() {
            let mut machine = a_machine_a_placement_wrote();
            assert_eq!(
                machine.start.role_state.read().expect("it reads"),
                RoleDesiredState::Disabled
            );
            assert_eq!(
                machine.start.look_after_the_role_worker(),
                "the role is disabled and no worker of this run is running",
                "nothing has ever been started under this run"
            );

            // **A role worker this run started and that has ended**: nothing is
            // admitted, so X9a's wait says it is over on the very pass the
            // disable arrives on. That is what Linux met.
            machine.start.the_role_worker = Some(TheRoleWorkerThisRunStarted {
                asked_under: Identity::issue(IdentityKind::Operation).expect("randomness"),
                group: ExecutionGroup {
                    kind: WorkerKind::Telegram,
                    leader: smoozy_runtime::execution_group::RecordedPair {
                        identifier: an_identifier_nothing_is_at(),
                        start_time: 1,
                    },
                },
                its_pair_was_taken: true,
                started_at: std::time::Instant::now(),
            });
            assert_eq!(
                machine.start.look_after_the_role_worker(),
                "the role is disabled and the worker this run started had already ended"
            );
            assert!(
                machine.start.the_role_worker.is_none(),
                "the ending was taken, so nothing stands to be signalled later"
            );
        }

        /// **A11a: not a role worker's work.** While the setup-in-progress state
        /// stands, enabling the role writes the state and starts nothing, and
        /// the caller is told which run stands in the way.
        #[test]
        fn enabling_the_role_while_a_setup_is_in_progress_writes_the_state_and_starts_nothing() {
            let mut machine = a_machine_a_placement_wrote();
            let run = Identity::issue(IdentityKind::Operation).expect("randomness");
            machine.start.setup_state.set(&run).expect("P4's write");

            let answered = answer(
                &a_role_request(THE_TELEGRAM_ROLE_IS_ENABLED_REQUEST),
                &mut machine.start,
            );
            assert_eq!(
                machine.start.role_state.read().expect("it reads"),
                RoleDesiredState::Enabled,
                "W8's write is not what A11 holds back"
            );
            let said = answered
                .fields
                .text(WHAT_THE_ROLE_WORKER_DID_FIELD)
                .expect("the caller is told");
            assert!(said.starts_with("not admitted"), "{said}");
            assert!(
                said.contains(&run.as_text()),
                "A5b: the refusal names the run — {said}"
            );
            assert_eq!(
                machine.start.wait.how_many_it_holds(),
                0,
                "nothing was started"
            );
        }

        /// **`Server protocol and transfers` C4 on this act too**: a repeat of
        /// an identity already recorded acts on nothing, so the state is not
        /// written a second time and no second worker is started.
        #[test]
        fn a_role_request_repeating_its_own_identity_acts_on_nothing() {
            let mut machine = a_machine_a_placement_wrote();
            a_program_at_the_pointer(&machine);
            let request = a_role_request(THE_TELEGRAM_ROLE_IS_ENABLED_REQUEST);
            answer(&request, &mut machine.start);
            let started = machine.start.wait.how_many_it_holds();

            let again = answer(&request, &mut machine.start);
            assert_eq!(
                again.fields.text(WHAT_THE_ROLE_WORKER_DID_FIELD),
                Some("that identity is already recorded and this acts on nothing")
            );
            assert_eq!(machine.start.wait.how_many_it_holds(), started);
        }

        // --- the Telegram worker's own requests (the first piece of the
        // Telegram worker's map, 2026-10-16) ---

        /// **A role worker started on this machine, and the process it is.**
        ///
        /// The stand-in at the pointer stays up, so the worker is still in the
        /// wait when it asks. **The kernel is pointed at a folder that holds
        /// nothing**, so no pair is taken here on any machine — the desk and
        /// Linux pose the same worker, held by the wait's own key.
        fn a_role_worker_on(machine: &mut AStartOverAnAreaThatGoesWithIt) -> u32 {
            a_program_at_the_pointer(machine);
            let nothing = machine.at.join("a kernel that publishes nothing");
            std::fs::create_dir_all(&nothing).expect("made");
            machine.start.worker_start.kernel.where_the_kernel_publishes = nothing;
            answer(
                &a_role_request(THE_TELEGRAM_ROLE_IS_ENABLED_REQUEST),
                &mut machine.start,
            );
            machine
                .start
                .the_role_worker
                .as_ref()
                .expect("the role worker this run started is held")
                .group
                .leader
                .identifier
        }

        fn a_workers_request(name: &str, fields: Fields) -> Request {
            a_role_request(name).carrying(fields)
        }

        fn the_state_store_in(
            answered: &Answered,
        ) -> smoozy_runtime::acting::stores::TheTelegramWorkersStateAsHeld {
            crate::the_telegram_worker::the_start_in(&answered.fields)
                .unwrap_or_else(|why| panic!("{why}: {answered:?}"))
                .state
        }

        /// **§6 item 2 of the Telegram worker's map: where a role worker starts
        /// and no pair can be taken, a later W8 act must not start a second.**
        ///
        /// Until 2026-10-16 such a worker was set to nothing here, the
        /// admission point admitted a second one beside it (the role kind's
        /// declaration reads as unlimited), and the second W8 act started it —
        /// two bots, and neither ending ever taken. **On that code this test
        /// found two workers in the wait.**
        #[test]
        fn a_role_worker_started_with_no_pair_is_held_and_a_later_enable_starts_no_second() {
            let mut machine = a_machine_a_placement_wrote();
            a_role_worker_on(&mut machine);
            assert_eq!(machine.start.wait.how_many_it_holds(), 1);
            let again = answer(
                &a_role_request(THE_TELEGRAM_ROLE_IS_ENABLED_REQUEST),
                &mut machine.start,
            );
            assert_eq!(
                again.fields.text(WHAT_THE_ROLE_WORKER_DID_FIELD),
                Some("the role worker is already running"),
                "{again:?}"
            );
            assert_eq!(
                machine.start.wait.how_many_it_holds(),
                1,
                "one bot, not two"
            );

            // **A worker held by the wait's key aims no signal**, and says so.
            let off = answer(
                &a_role_request(THE_TELEGRAM_ROLE_IS_DISABLED_REQUEST),
                &mut machine.start,
            );
            let said = off
                .fields
                .text(WHAT_THE_ROLE_WORKER_DID_FIELD)
                .expect("said");
            assert!(
                said.contains("was not signalled: no pair was taken"),
                "{said}"
            );
        }

        /// **§5.3's paragraph after W7: the worker's own requests are answered
        /// only from the role worker this run started.** Every one of the six
        /// is refused — told to end itself — with no process beside it, from a
        /// process that is not the worker, and on a machine holding no worker at
        /// all; and the worker itself is answered.
        #[test]
        fn the_workers_own_requests_are_answered_from_this_runs_role_worker_alone() {
            let mut machine = a_machine_a_placement_wrote();
            for name in crate::the_telegram_worker::THE_TELEGRAM_WORKERS_OWN_REQUESTS {
                let refused = answer(&a_role_request(name), &mut machine.start);
                assert!(
                    crate::the_telegram_worker::it_says_end_yourself(&refused),
                    "{name} with no worker held: {refused:?}"
                );
            }
            let worker = a_role_worker_on(&mut machine);
            for name in crate::the_telegram_worker::THE_TELEGRAM_WORKERS_OWN_REQUESTS {
                for caller in [None, Some(worker.wrapping_add(1))] {
                    let refused = answer_knowing_the_caller(
                        &a_role_request(name),
                        caller,
                        &mut machine.start,
                    );
                    assert!(
                        crate::the_telegram_worker::it_says_end_yourself(&refused),
                        "{name} from {caller:?}: {refused:?}"
                    );
                }
            }
            let answered = answer_knowing_the_caller(
                &a_role_request(THE_TELEGRAM_WORKERS_START_REQUEST),
                Some(worker),
                &mut machine.start,
            );
            assert!(!crate::the_telegram_worker::it_says_end_yourself(&answered));
            assert_eq!(
                the_state_store_in(&answered).update_position,
                None,
                "nothing yet"
            );
        }

        /// **`Telegram` F2: one fact written through the supervisor is read back
        /// by the worker a new supervisor run starts** — and the worker of the
        /// earlier run is refused by the new one.
        #[test]
        fn a_workers_fact_is_read_back_across_a_new_supervisor_run() {
            let mut machine = a_machine_a_placement_wrote();
            let first = a_role_worker_on(&mut machine);
            for fact in [
                crate::the_telegram_worker::AFact::TheUpdatePosition(1_234),
                crate::the_telegram_worker::AFact::TheStatusMessage(77),
                crate::the_telegram_worker::AFact::AnActionContext {
                    identity: "ab".repeat(16),
                    record: "{\"action\":\"stop\"}".to_string(),
                },
            ] {
                let wrote = answer_knowing_the_caller(
                    &a_workers_request(
                        THE_TELEGRAM_WORKERS_FACT_REQUEST,
                        crate::the_telegram_worker::the_fact_as_fields(&fact).expect("it writes"),
                    ),
                    Some(first),
                    &mut machine.start,
                );
                assert_eq!(
                    wrote.fields.text(WHAT_BECAME_OF_THE_WRITE_FIELD),
                    Some(IT_WAS_WRITTEN),
                    "{wrote:?}"
                );
            }

            the_supervisor_starts_again(&mut machine);
            machine.start.worker_start.kernel.where_the_kernel_publishes =
                machine.at.join("a kernel that publishes nothing");
            machine.start.look_after_the_role_worker();
            let second = machine
                .start
                .the_role_worker
                .as_ref()
                .expect("the new run started its own worker")
                .group
                .leader
                .identifier;
            assert_ne!(first, second);

            let the_old_one = answer_knowing_the_caller(
                &a_role_request(THE_TELEGRAM_WORKERS_START_REQUEST),
                Some(first),
                &mut machine.start,
            );
            assert!(
                crate::the_telegram_worker::it_says_end_yourself(&the_old_one),
                "a role worker of an earlier run is told to end itself: {the_old_one:?}"
            );
            let started = answer_knowing_the_caller(
                &a_role_request(THE_TELEGRAM_WORKERS_START_REQUEST),
                Some(second),
                &mut machine.start,
            );
            let held = the_state_store_in(&started);
            assert_eq!(held.update_position, Some(1_234));
            assert_eq!(held.status_message, Some(77));
            assert_eq!(
                held.action_contexts
                    .get(&"ab".repeat(16))
                    .map(String::as_str),
                Some("{\"action\":\"stop\"}")
            );
        }

        /// **The worker's cursor move writes its cursor in its store and the
        /// journal's registration for the Telegram worker — and never the
        /// desktop's** (`State, identity and recovery` E2 and `State, identity and recovery` E6).
        #[test]
        fn the_workers_cursor_moves_its_own_cursor_and_registration_and_not_the_desktops() {
            let mut machine = a_machine_a_placement_wrote();
            let worker = a_role_worker_on(&mut machine);
            for at in 0..4 {
                machine
                    .start
                    .journal("a kind", &format!("event {at}"))
                    .expect("journalled");
            }
            machine
                .start
                .journal
                .a_reader_has_passed(ARegisteredReader::TheDesktop, 1)
                .expect("the desktop's cursor");
            let newest = machine.start.journal.next_sequence();
            let a_move = |to: u64| {
                a_workers_request(
                    THE_TELEGRAM_WORKERS_CURSOR_MOVES_REQUEST,
                    Fields::none().and(asked::THE_CURSOR_FIELD, to.to_string()),
                )
            };

            let moved =
                answer_knowing_the_caller(&a_move(newest - 1), Some(worker), &mut machine.start);
            assert_eq!(
                moved.fields.text(WHAT_BECAME_OF_THE_WRITE_FIELD),
                Some(IT_WAS_WRITTEN),
                "{moved:?}"
            );
            assert_eq!(
                machine
                    .start
                    .the_telegram_workers_state
                    .read()
                    .expect("reads")
                    .journal_cursor,
                Some(newest - 1),
                "the cursor is in the worker's store"
            );
            let registrations = machine.start.journal.every_registration().clone();
            assert_eq!(
                registrations.get(&ARegisteredReader::TheTelegramWorker),
                Some(&(newest - 1))
            );
            assert_eq!(
                registrations.get(&ARegisteredReader::TheDesktop),
                Some(&1),
                "the desktop's cursor is not moved"
            );

            // **Never backwards, never past the newest.**
            let behind = answer_knowing_the_caller(&a_move(1), Some(worker), &mut machine.start);
            assert_eq!(
                behind.fields.text(asked::THE_CURSOR_FIELD),
                Some((newest - 1).to_string().as_str())
            );
            let past =
                answer_knowing_the_caller(&a_move(newest + 5), Some(worker), &mut machine.start);
            assert_eq!(
                past.fields.text(WHAT_BECAME_OF_THE_WRITE_FIELD),
                Some(IT_WAS_NOT_WRITTEN)
            );
            assert_eq!(
                machine
                    .start
                    .the_telegram_workers_state
                    .read()
                    .expect("reads")
                    .journal_cursor,
                Some(newest - 1)
            );

            // **The read forward starts at the cursor the store holds.**
            let read = answer_knowing_the_caller(
                &a_role_request(THE_TELEGRAM_WORKERS_READ_FORWARD_REQUEST),
                Some(worker),
                &mut machine.start,
            );
            assert_eq!(
                read.fields.text(asked::HOW_MANY_EVENTS_FIELD),
                Some("1"),
                "{read:?}"
            );
        }

        /// **`State, identity and recovery` §2.2: the routing key is issued when
        /// the role is first enabled, and kept** — through a disable, a second
        /// enable and the worker's own start.
        #[test]
        fn the_routing_key_is_issued_at_the_first_enable_and_kept() {
            let mut machine = a_machine_a_placement_wrote();
            assert_eq!(
                machine
                    .start
                    .the_telegram_workers_state
                    .read()
                    .expect("reads")
                    .routing_key,
                None,
                "nothing has enabled the role yet"
            );
            let worker = a_role_worker_on(&mut machine);
            let key = machine
                .start
                .the_telegram_workers_state
                .read()
                .expect("reads")
                .routing_key
                .expect("W8's enable issued it");
            assert_eq!(key.len(), 32, "16 bytes, as hexadecimal text");
            assert!(key.chars().all(|c| c.is_ascii_hexdigit()));

            let started = answer_knowing_the_caller(
                &a_role_request(THE_TELEGRAM_WORKERS_START_REQUEST),
                Some(worker),
                &mut machine.start,
            );
            assert_eq!(
                started
                    .fields
                    .text(crate::the_telegram_worker::THE_ROUTING_KEY_FIELD),
                Some(key.as_str())
            );

            answer(
                &a_role_request(THE_TELEGRAM_ROLE_IS_DISABLED_REQUEST),
                &mut machine.start,
            );
            answer(
                &a_role_request(THE_TELEGRAM_ROLE_IS_ENABLED_REQUEST),
                &mut machine.start,
            );
            assert_eq!(
                machine
                    .start
                    .the_telegram_workers_state
                    .read()
                    .expect("reads")
                    .routing_key,
                Some(key),
                "never issued again"
            );
        }

        /// **`Telegram` B9: an instruction's outcome is recorded beside its
        /// identity, the first recorded stands, and a reading finds it.**
        #[test]
        fn an_instructions_first_recorded_outcome_stands() {
            let mut machine = a_machine_a_placement_wrote();
            let worker = a_role_worker_on(&mut machine);
            let reading = || {
                a_workers_request(
                    THE_INSTRUCTIONS_OUTCOME_READING_REQUEST,
                    Fields::none().and(THE_INSTRUCTION_FIELD, "tap-1"),
                )
            };
            let recording = |outcome: AnInstructionsOutcome| {
                a_workers_request(
                    THE_INSTRUCTIONS_OUTCOME_IS_RECORDED_REQUEST,
                    Fields::none()
                        .and(THE_INSTRUCTION_FIELD, "tap-1")
                        .and(THE_OUTCOME_FIELD, outcome.as_recorded()),
                )
            };
            let before = answer_knowing_the_caller(&reading(), Some(worker), &mut machine.start);
            assert_eq!(
                before.fields.text(WHAT_IS_RECORDED_FIELD),
                Some(NOTHING_IS_RECORDED)
            );

            let first = answer_knowing_the_caller(
                &recording(AnInstructionsOutcome::NotDone(
                    "the subject has ended".into(),
                )),
                Some(worker),
                &mut machine.start,
            );
            assert_eq!(
                first.fields.text(WHAT_BECAME_OF_THE_WRITE_FIELD),
                Some(IT_WAS_WRITTEN)
            );
            let second = answer_knowing_the_caller(
                &recording(AnInstructionsOutcome::Done),
                Some(worker),
                &mut machine.start,
            );
            assert_eq!(
                second.fields.text(WHAT_BECAME_OF_THE_WRITE_FIELD),
                Some(IT_WAS_ALREADY_RECORDED)
            );
            assert_eq!(
                second.fields.text(THE_OUTCOME_FIELD),
                Some("not done: the subject has ended")
            );

            let after = answer_knowing_the_caller(&reading(), Some(worker), &mut machine.start);
            assert_eq!(
                after.fields.text(WHAT_IS_RECORDED_FIELD),
                Some(AN_OUTCOME_IS_RECORDED)
            );
            assert_eq!(
                after.fields.text(THE_OUTCOME_FIELD),
                Some("not done: the subject has ended")
            );
        }

        // --- the Telegram worker itself, assembled in this process against the
        // supervisor's real answers (the second piece of the Telegram worker's
        // map, 2026-10-16) ---

        /// What a test asks of a supervisor running on a thread of its own.
        enum ToTheSupervisor {
            /// One request, from the process named, and where its answer goes.
            Ask(Request, u32, std::sync::mpsc::Sender<Answered>),
            /// S4's restart: a fresh run over the same area, and the role worker
            /// that run starts. Its process comes back.
            StartsAgain(std::sync::mpsc::Sender<u32>),
            /// The worker's state store, read off the disk.
            TheStore(
                std::sync::mpsc::Sender<
                    smoozy_runtime::acting::stores::TheTelegramWorkersStateAsHeld,
                >,
            ),
            /// **Anything done on the machine itself, on its thread** — a job
            /// written, ended or held, an event journalled — the way the
            /// map's piece 3 poses what the journal reader reads. Its sender
            /// is told when it is done.
            OnTheMachine(
                Box<dyn FnOnce(&mut AStartOverAnAreaThatGoesWithIt) + Send>,
                std::sync::mpsc::Sender<()>,
            ),
            /// The test is over: the stand-ins are killed and the area goes,
            /// whatever worker still holds a way to ask.
            End,
        }

        /// **A real supervisor's start over a package area of its own, on a
        /// thread of its own**, answering every request with the very function
        /// its loop calls ([`answer_knowing_the_caller`]). A supervisor's start is
        /// not something a second thread may touch, so it is made on its thread
        /// and never leaves it; the worker's store asks it over a channel.
        ///
        /// **Its role worker is a stand-in that stays up** — the same shape
        /// [`a_program_at_the_pointer`] writes, given longer — and is killed when
        /// this goes. The kernel is pointed at a folder that publishes nothing, so
        /// the desk and Linux pose the same worker, held by the wait's own key.
        struct ASupervisorOnAThreadOfItsOwn {
            to: Option<std::sync::mpsc::Sender<ToTheSupervisor>>,
            thread: Option<std::thread::JoinHandle<()>>,
            /// The process of the role worker the current run started.
            worker: u32,
            /// **Its package area**, which the worker's records are read from.
            at: PathBuf,
        }

        impl ASupervisorOnAThreadOfItsOwn {
            fn started() -> ASupervisorOnAThreadOfItsOwn {
                let (to, asked) = std::sync::mpsc::channel::<ToTheSupervisor>();
                let (said, heard) = std::sync::mpsc::channel::<(u32, PathBuf)>();
                let thread = std::thread::spawn(move || {
                    use std::os::unix::fs::PermissionsExt;
                    let mut machine = a_machine_a_placement_wrote();
                    let at = machine
                        .at
                        .join(smoozy_runtime::the_program::THE_FIXED_ENTRY_POINT_NAME);
                    std::fs::write(&at, "#!/bin/sh\nexec sleep 600\n")
                        .expect("the stand-in is written");
                    std::fs::set_permissions(&at, std::fs::Permissions::from_mode(0o755))
                        .expect("it is made runnable");
                    let nothing = machine.at.join("a kernel that publishes nothing");
                    std::fs::create_dir_all(&nothing).expect("made");
                    machine.start.worker_start.kernel.where_the_kernel_publishes = nothing;
                    answer(
                        &a_role_request(THE_TELEGRAM_ROLE_IS_ENABLED_REQUEST),
                        &mut machine.start,
                    );
                    let the_role_worker = |machine: &AStartOverAnAreaThatGoesWithIt| {
                        machine
                            .start
                            .the_role_worker
                            .as_ref()
                            .expect("the role worker this run started is held")
                            .group
                            .leader
                            .identifier
                    };
                    let mut every_worker = vec![the_role_worker(&machine)];
                    let _ = said.send((every_worker[0], machine.at.clone()));
                    for asking in asked {
                        match asking {
                            ToTheSupervisor::Ask(request, process, back) => {
                                let _ = back.send(answer_knowing_the_caller(
                                    &request,
                                    Some(process),
                                    &mut machine.start,
                                ));
                            }
                            ToTheSupervisor::StartsAgain(back) => {
                                the_supervisor_starts_again(&mut machine);
                                machine.start.look_after_the_role_worker();
                                every_worker.push(the_role_worker(&machine));
                                let _ = back.send(*every_worker.last().expect("one"));
                            }
                            ToTheSupervisor::TheStore(back) => {
                                let _ = back.send(
                                    machine
                                        .start
                                        .the_telegram_workers_state
                                        .read()
                                        .expect("it reads"),
                                );
                            }
                            ToTheSupervisor::OnTheMachine(what, back) => {
                                what(&mut machine);
                                let _ = back.send(());
                            }
                            ToTheSupervisor::End => break,
                        }
                    }
                    for worker in every_worker {
                        // SAFETY: a signal to a child this test started and holds
                        // in its wait, so the identifier is its own.
                        unsafe { libc::kill(worker as libc::pid_t, libc::SIGKILL) };
                    }
                });
                let (worker, at) = heard
                    .recv()
                    .expect("the supervisor started its role worker");
                ASupervisorOnAThreadOfItsOwn {
                    to: Some(to),
                    thread: Some(thread),
                    worker,
                    at,
                }
            }

            fn sender(&self) -> std::sync::mpsc::Sender<ToTheSupervisor> {
                self.to.clone().expect("it is running")
            }

            /// **The worker's way to it**, asking as `process`.
            fn asked_as(
                &self,
                process: u32,
            ) -> std::sync::Arc<dyn crate::the_telegram_worker::AsksTheSupervisor> {
                std::sync::Arc::new(AskedOverAChannel {
                    to: std::sync::Mutex::new(self.sender()),
                    process,
                })
            }

            fn starts_again(&mut self) -> u32 {
                let (back, answer) = std::sync::mpsc::channel();
                self.sender()
                    .send(ToTheSupervisor::StartsAgain(back))
                    .expect("sent");
                self.worker = answer.recv().expect("a new run started its role worker");
                self.worker
            }

            fn the_store(&self) -> smoozy_runtime::acting::stores::TheTelegramWorkersStateAsHeld {
                let (back, answer) = std::sync::mpsc::channel();
                self.sender()
                    .send(ToTheSupervisor::TheStore(back))
                    .expect("sent");
                answer.recv().expect("read")
            }

            /// **Something done on the machine, on its thread**, and waited for.
            fn on_the_machine(
                &self,
                what: impl FnOnce(&mut AStartOverAnAreaThatGoesWithIt) + Send + 'static,
            ) {
                let (back, done) = std::sync::mpsc::channel();
                self.sender()
                    .send(ToTheSupervisor::OnTheMachine(Box::new(what), back))
                    .expect("sent");
                done.recv().expect("done on the machine");
            }
        }

        impl Drop for ASupervisorOnAThreadOfItsOwn {
            fn drop(&mut self) {
                // **Ended by a word and not by the channel closing**: a worker
                // the test still holds keeps a way to ask, and waiting for it
                // to go would hang a test that failed before dropping it.
                if let Some(to) = self.to.take() {
                    let _ = to.send(ToTheSupervisor::End);
                }
                if let Some(thread) = self.thread.take() {
                    let _ = thread.join();
                }
            }
        }

        /// The worker's requests, carried to the supervisor's thread.
        struct AskedOverAChannel {
            to: std::sync::Mutex<std::sync::mpsc::Sender<ToTheSupervisor>>,
            process: u32,
        }

        impl crate::the_telegram_worker::AsksTheSupervisor for AskedOverAChannel {
            fn ask(&self, request: &Request) -> Result<Option<Answered>, String> {
                let (back, answer) = std::sync::mpsc::channel();
                self.to
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .send(ToTheSupervisor::Ask(request.clone(), self.process, back))
                    .map_err(|_| "the supervisor's thread has ended".to_string())?;
                Ok(answer.recv().ok())
            }
        }

        /// What one simulated machine holds, set by the test.
        #[derive(Clone, Default)]
        struct JobsHeldHere(
            std::sync::Arc<std::sync::Mutex<Vec<smoozy_telegram::routing::gather::AJobAsHeld>>>,
        );

        impl smoozy_telegram::routing::gather::ReadsWhatThisMachineHolds for JobsHeldHere {
            fn the_jobs(&self) -> Vec<smoozy_telegram::routing::gather::AJobAsHeld> {
                self.0
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .clone()
            }
        }

        /// **One machine's worker, put together by the function the mode calls**,
        /// over its own supervisor, asking as `process`, on the shared simulated
        /// conversation and clock. `caller` names its client in what the
        /// conversation heard.
        fn a_worker_on(
            supervisor: &ASupervisorOnAThreadOfItsOwn,
            process: u32,
            name: &str,
            caller: &str,
            sim: &std::sync::Arc<crate::the_telegram_worker::a_simulated_conversation::Sim>,
            clock: &std::sync::Arc<
                crate::the_telegram_worker::a_simulated_conversation::TheTestsClock,
            >,
            holds: JobsHeldHere,
        ) -> (
            crate::the_telegram_worker::TheAssembledWorker,
            crate::the_telegram_worker::TheWorkersStart,
        ) {
            a_worker_configured(
                supervisor,
                process,
                name,
                caller,
                sim,
                clock,
                holds,
                Vec::new(),
                std::sync::Arc::new(std::time::SystemTime::now),
            )
        }

        /// **The same, with V2's switches and the machine's own now handed
        /// in** — the map's piece 3, whose idle message reads both.
        #[allow(clippy::too_many_arguments)]
        fn a_worker_configured(
            supervisor: &ASupervisorOnAThreadOfItsOwn,
            process: u32,
            name: &str,
            caller: &str,
            sim: &std::sync::Arc<crate::the_telegram_worker::a_simulated_conversation::Sim>,
            clock: &std::sync::Arc<
                crate::the_telegram_worker::a_simulated_conversation::TheTestsClock,
            >,
            holds: JobsHeldHere,
            reporting: Vec<(String, bool)>,
            the_machines_now: std::sync::Arc<dyn Fn() -> std::time::SystemTime + Send + Sync>,
        ) -> (
            crate::the_telegram_worker::TheAssembledWorker,
            crate::the_telegram_worker::TheWorkersStart,
        ) {
            use crate::the_telegram_worker::a_simulated_conversation::{NoWaits, THE_CONVERSATION};
            let asked = supervisor.asked_as(process);
            let start = crate::the_telegram_worker::the_start_asked(asked.as_ref(), Duration::ZERO)
                .expect("this run's worker is given its start");
            let worker = crate::the_telegram_worker::the_worker_assembled(
                crate::the_telegram_worker::WhatTheWorkerIsHanded {
                    client: sim.a_client_for(caller),
                    clock: clock.clone(),
                    waits: std::sync::Arc::new(NoWaits),
                    supervisor: asked,
                    start: start.clone(),
                    configuration: smoozy_telegram::material::TheRoleConfiguration {
                        conversation: smoozy_telegram::proof::TheConversation(THE_CONVERSATION),
                        machine: format!("machine-{name}"),
                        colour: None,
                        label: Some(format!("Server {}", name.to_uppercase())),
                        reporting,
                    },
                    holds: Box::new(holds),
                    package_area: supervisor.at.clone(),
                    the_machines_now,
                    readings: Box::new(crate::the_telegram_worker::a_simulated_conversation::TheReadingsATestSets::default()),
                    notes: std::sync::Arc::new(|_| {}),
                },
            );
            (worker, start)
        }

        /// One read cadence: every worker's turn, then the clock moves on.
        fn a_round_of(
            workers: &mut [&mut crate::the_telegram_worker::TheAssembledWorker],
            clock: &crate::the_telegram_worker::a_simulated_conversation::TheTestsClock,
        ) {
            for worker in workers.iter_mut() {
                worker.a_turn_by_hand();
            }
            clock.moved_on_by(smoozy_telegram::board::staleness::THE_READ_CADENCE);
        }

        /// **Rounds until `done`**, at most `most` of them; the rounds taken.
        fn rounds_until(
            most: usize,
            workers: &mut [&mut crate::the_telegram_worker::TheAssembledWorker],
            clock: &crate::the_telegram_worker::a_simulated_conversation::TheTestsClock,
            done: &dyn Fn(&[&mut crate::the_telegram_worker::TheAssembledWorker]) -> bool,
        ) -> Option<usize> {
            for round in 0..most {
                if done(workers) {
                    return Some(round);
                }
                a_round_of(workers, clock);
            }
            done(workers).then_some(most)
        }

        fn how_many_hold(workers: &[&mut crate::the_telegram_worker::TheAssembledWorker]) -> usize {
            workers.iter().filter(|worker| worker.is_holding()).count()
        }

        /// **Two machines, each with its own supervisor, settled**: one holds the
        /// slot and both are on the board's roster.
        #[allow(clippy::type_complexity)]
        fn two_machines_settled() -> (
            std::sync::Arc<crate::the_telegram_worker::a_simulated_conversation::Sim>,
            std::sync::Arc<crate::the_telegram_worker::a_simulated_conversation::TheTestsClock>,
            [ASupervisorOnAThreadOfItsOwn; 2],
            [crate::the_telegram_worker::TheAssembledWorker; 2],
            [JobsHeldHere; 2],
        ) {
            let sim = std::sync::Arc::new(
                crate::the_telegram_worker::a_simulated_conversation::Sim::default(),
            );
            let clock = std::sync::Arc::new(
                crate::the_telegram_worker::a_simulated_conversation::TheTestsClock::default(),
            );
            let (on_a, on_b) = (
                ASupervisorOnAThreadOfItsOwn::started(),
                ASupervisorOnAThreadOfItsOwn::started(),
            );
            let held = [JobsHeldHere::default(), JobsHeldHere::default()];
            let (mut a, _) =
                a_worker_on(&on_a, on_a.worker, "a", "a", &sim, &clock, held[0].clone());
            let (mut b, _) =
                a_worker_on(&on_b, on_b.worker, "b", "b", &sim, &clock, held[1].clone());
            let on_the_roster =
                |sim: &crate::the_telegram_worker::a_simulated_conversation::Sim| {
                    sim.the_board_on_top()
                        .is_some_and(|(_, board)| board.roster.len() == 2)
                };
            // **Since 2026-10-18 the machine that does not hold announces only
            // once it has seen the holder's first renewal** (`Telegram` B14,
            // the Creator's fourteenth notes, note 2), about fifty seconds
            // after the claim: the bound was 80 rounds.
            {
                let sim = sim.clone();
                rounds_until(120, &mut [&mut a, &mut b], &clock, &|workers| {
                    how_many_hold(workers) == 1 && on_the_roster(&sim)
                })
                .expect("one machine holds and both are on the roster");
            }
            (sim, clock, [on_a, on_b], [a, b], held)
        }

        #[test]
        fn twenty_first_a_down_line_keeps_the_event_then_three_reaches_pass_it_and_say_it_once() {
            for lose_notice in [false, true] {
                let (sim, clock, on, mut worker) = one_worker_reading_its_journal(
                    Vec::new(),
                    std::sync::Arc::new(std::time::SystemTime::now),
                );
                let logs = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
                let copy = logs.clone();
                worker
                    .the_journal()
                    .record_notes_with(std::sync::Arc::new(move |line| {
                        copy.lock().unwrap().push(line.into())
                    }));
                let (job, operation) = sixteenth_job(&on, "Video", vec![1, 2], true, false);
                a_finished_video_of(&on, &job, 2_000);
                a_video_job_finishes(&on, &job, &operation, asked::IT_FINISHED);
                let cursor = on.the_store().journal_cursor;
                sim.state().unreachable_callers.insert("a".into());
                for _ in 0..8 {
                    worker.the_journal().a_turn();
                }
                assert_eq!(
                    on.the_store().journal_cursor,
                    cursor,
                    "a down line loses no ending"
                );
                assert!(!logs
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|line| line.contains("passed after")));
                sim.state().unreachable_callers.clear();
                sim.state()
                    .broken_texts
                    .push(("a".into(), "Video\nFinished.".into()));
                if lose_notice {
                    sim.state().broken_texts.push((
                        "a".into(),
                        "A message about this job could not be sent.".into(),
                    ));
                }
                for turn in 0..18 {
                    a_round_of(&mut [&mut worker], &clock);
                    if lose_notice && turn == 3 {
                        assert_eq!(
                            on.the_store().journal_cursor,
                            cursor,
                            "an unsent notice keeps the saved place, so a restart cannot forget it"
                        );
                    }
                }
                assert!(
                    on.the_store().journal_cursor > cursor,
                    "the event was passed"
                );
                let said = sim.said_to_the_user();
                let notices = said
                    .iter()
                    .filter(|text| text.contains("A message about this job could not be sent."))
                    .count();
                assert_eq!(notices, usize::from(!lose_notice));
                let logs = logs.lock().unwrap();
                assert!(logs
                    .iter()
                    .any(|line| line.contains("kind ") && line.contains("counted tries 3")));
                assert!(logs.iter().any(|line| line.contains("event ")
                    && line.contains(&job.as_text())
                    && line.contains("not reached")));
                assert_eq!(
                    logs.iter()
                        .filter(|line| line.contains("one unsent notice is owed"))
                        .count(),
                    1
                );
                assert_eq!(
                    logs.iter()
                        .filter(|line| line.contains("no further notice"))
                        .count(),
                    usize::from(lose_notice)
                );
            }
        }

        /// Note 8: both real workers share one bot and chat. A failed picture
        /// on B used to hold its video ending forever, although status went on.
        #[test]
        fn twenty_first_two_servers_a_bad_send_never_hides_the_video_ending() {
            for broken_send in [false, true] {
                let (sim, clock, [on_a, on_b], [mut a, mut b], _) = two_machines_settled();
                let (send, receive) = std::sync::mpsc::channel();
                on_b.on_the_machine(move |machine| {
                    let (check, operation) = a_render_running(machine, "Pipe check", vec![1], None);
                    let (range, hold) = a_hold_placed_on(
                        machine,
                        "Pipe",
                        (1..=90).collect(),
                        Some(&check),
                        "the first-frame check",
                    );
                    a_frame_produced_with_its_layers(machine, &check, 1, &[("Main", 0)]);
                    the_render_reports_its_ending(machine, &operation, asked::IT_FINISHED, None);
                    send.send((range, hold)).unwrap();
                });
                let (range, hold) = receive.recv().unwrap();
                for _ in 0..4 {
                    a_round_of(&mut [&mut a, &mut b], &clock);
                }
                assert!(sim
                    .said_to_the_user()
                    .iter()
                    .any(|text| text.contains("Pipe · frames 1–90\nNeeds your answer.")));
                on_b.on_the_machine(move |machine| {
                    let answered = answer(
                        &an_answer_to(&hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK),
                        &mut machine.start,
                    );
                    assert_eq!(
                        answered.fields.text(THE_RELEASE_OUTCOME_FIELD),
                        Some("released")
                    );
                });
                let (video, operation) =
                    sixteenth_job_as(&on_b, "Pipe", (1..=90).collect(), true, false, range);
                let started = video.clone();
                on_b.on_the_machine(move |machine| {
                    machine
                        .start
                        .journal_about(
                            asked::THE_RENDER_ATTEMPT_STARTED_EVENT,
                            Some(started),
                            "attempt 1",
                        )
                        .unwrap();
                });
                for _ in 0..4 {
                    a_round_of(&mut [&mut a, &mut b], &clock);
                }
                assert!(sim
                    .said_to_the_user()
                    .iter()
                    .any(|text| text.starts_with("Server B\nPipe\nStarted.")));
                // Another queued picture fails persistently on B; all other calls
                // still reach the shared chat. A is sending pictures throughout.
                if broken_send {
                    sim.state().broken_pictures_from.insert("b".into());
                }
                let (send, receive) = std::sync::mpsc::channel();
                on_a.on_the_machine(move |machine| {
                    let (job, operation) = a_render_running(machine, "Racket", vec![1, 2, 3], None);
                    its_choice_is_everything(&the_record_directory_of(machine, &job));
                    send.send((job, operation)).unwrap();
                });
                let (racket, racket_operation) = receive.recv().unwrap();
                on_b.on_the_machine(|machine| {
                    let (job, _) = a_render_running(machine, "Broken picture", vec![1], None);
                    its_choice_is_everything(&the_record_directory_of(machine, &job));
                    a_frame_produced_with_its_layers(machine, &job, 1, &[("Main", 0)]);
                });
                a_finished_video_of(&on_b, &video, 2_000);
                a_video_job_finishes(&on_b, &video, &operation, asked::IT_FINISHED);
                for frame in 1..=3 {
                    a_frame_is_produced(&on_a, &racket, frame, 1);
                    for _ in 0..4 {
                        a_round_of(&mut [&mut a, &mut b], &clock);
                    }
                    assert_eq!(
                        sim.calls("a", "sendPhoto").len(),
                        frame as usize,
                        "A keeps reporting"
                    );
                }
                on_a.on_the_machine(move |machine| {
                    the_render_reports_its_ending(
                        machine,
                        &racket_operation,
                        asked::IT_FINISHED,
                        None,
                    );
                });
                for _ in 0..12 {
                    a_round_of(&mut [&mut a, &mut b], &clock);
                }
                let said = sim.said_to_the_user();
                said_once(&said, "Server A\nRacket\nFinished.");
                said_once(&said, "Server B\nPipe\nFinished.");
                assert_eq!(
                    sim.calls("b", "sendVideo").len(),
                    1,
                    "B's finished video must arrive"
                );
                assert!(sim.status_calls("b").len() > 3, "B keeps turning");
                let notices = said
                    .iter()
                    .filter(|text| text.contains("A message about this job could not be sent."))
                    .count();
                assert_eq!(notices, usize::from(broken_send));
            }
        }

        /// **The map's piece 2, first proof: two assembled workers, one holds
        /// the slot and the other stands down** — and goes on standing down, the
        /// board naming the holder, the holder's board identity written through
        /// its own supervisor into its own store, and the other's machinery
        /// message through its own.
        #[test]
        fn two_assembled_workers_one_holds_the_slot_and_the_other_stands_down() {
            let (sim, clock, [on_a, on_b], [mut a, mut b], _) = two_machines_settled();
            let holder_is_a = a.is_holding();
            for _ in 0..30 {
                a_round_of(&mut [&mut a, &mut b], &clock);
                assert_eq!(a.is_holding(), holder_is_a, "the slot does not move");
                assert_ne!(a.is_holding(), b.is_holding(), "exactly one holds");
            }
            let (top, board) = sim.the_board_on_top().expect("a board is pinned");
            let (holder, other) = if holder_is_a {
                (&on_a, &on_b)
            } else {
                (&on_b, &on_a)
            };
            assert_eq!(
                board.holder,
                if holder_is_a {
                    "machine-a"
                } else {
                    "machine-b"
                }
            );
            assert_eq!(
                holder.the_store().board,
                Some(top),
                "`Telegram` F2: written by its supervisor"
            );
            assert!(
                other.the_store().machinery_message.is_some(),
                "the other announced itself through its own"
            );
            assert_eq!(sim.state().pins, vec![top], "the board is the one pin");
        }

        /// **`Telegram` B18, through two assembled workers: every line a pin of
        /// Smoozy's wrote is deleted once processed, and nothing else is asked
        /// to be deleted.** The two settle — boards and machinery messages
        /// pinned as they claim and announce — and read on. Then a stray
        /// machinery message is pinned, as one from a machine since gone, and
        /// its line is already two days old when it is reached: Telegram
        /// refuses it, it stays, and the stray message is taken in and unpinned
        /// all the same.
        #[test]
        fn two_assembled_workers_delete_every_line_their_pins_wrote_and_nothing_else() {
            let (sim, clock, _supervisors, [mut a, mut b], _) = two_machines_settled();
            for _ in 0..10 {
                a_round_of(&mut [&mut a, &mut b], &clock);
            }
            let deleted = {
                let s = sim.state();
                // At least the board's line and the other machine's announcement's.
                assert!(
                    s.deleted.len() >= 2,
                    "settling wrote and deleted {} lines",
                    s.deleted.len()
                );
                assert!(
                    s.lines.is_empty(),
                    "`Telegram` B18: lines still standing: {:?}",
                    s.lines
                );
                assert!(
                    s.asked_to_delete_what_is_not_a_line.is_empty(),
                    "`Telegram` B18: {:?}",
                    s.asked_to_delete_what_is_not_a_line
                );
                assert_eq!(s.pins.len(), 1, "the board is the one pin");
                s.deleted.len()
            };

            let stray = sim.a_message_from_the_bot(
                &smoozy_telegram::board::text::TheUtterance {
                    machine: "machine-gone".into(),
                    display: "Server Gone".into(),
                    ..Default::default()
                }
                .compose()
                .expect("composed"),
            );
            sim.a_client_for("a machine since gone")
                .pin_chat_message(
                    crate::the_telegram_worker::a_simulated_conversation::THE_CONVERSATION,
                    stray,
                )
                .expect("pinned");
            let line = {
                let mut s = sim.state();
                let line = *s.lines.keys().next().expect("the stray pin wrote a line");
                s.past_two_days.insert(line);
                line
            };
            for _ in 0..10 {
                a_round_of(&mut [&mut a, &mut b], &clock);
            }
            let s = sim.state();
            assert!(
                !s.pins.contains(&stray),
                "the stray message was taken in and unpinned"
            );
            assert_eq!(
                s.lines.keys().copied().collect::<Vec<_>>(),
                vec![line],
                "the line past two days stays"
            );
            assert_eq!(s.deleted.len(), deleted, "and nothing else was deleted");
            let asked = s
                .heard
                .iter()
                .filter(|(_, m, f)| {
                    m == "deleteMessage" && f["message_id"] == serde_json::json!(line)
                })
                .count();
            assert_eq!(asked, 1, "asked once, refused, and not asked again");
            assert!(s.asked_to_delete_what_is_not_a_line.is_empty());
        }

        /// **The map's piece 2, second proof: a tap reaches its owner** through
        /// two assembled workers — a stop button issued by the machine that does
        /// not hold, the tap heard by the one that does, resolved across the
        /// board and acted on once by its owner. ~~**The act itself is the map's
        /// piece 4's**, so the owner records it as not done~~ **Since the map's
        /// piece 4 the owner acts on the machine's own line**, and the job here
        /// is one only this test's reader holds, so the owner records the stop
        /// not done, with the machine's reason, through its own supervisor,
        /// beside the instruction's identity (`Telegram` B9), and the user is
        /// told so. The stop reaching a real render is
        /// `a_stop_tapped_on_the_phone_reaches_the_render_and_ends_it_left_stopped`.
        #[test]
        fn a_tap_reaches_its_owner_through_two_assembled_workers() {
            let (sim, clock, [on_a, on_b], [mut a, mut b], held) = two_machines_settled();
            let owner_is_b = a.is_holding();
            let (name, on, jobs) = if owner_is_b {
                ("b", &on_b, &held[1])
            } else {
                ("a", &on_a, &held[0])
            };
            let (back, got) = std::sync::mpsc::channel();
            on.on_the_machine(move |machine| {
                let pair = a_render_running(machine, "Remote", vec![1], None);
                back.send(pair).unwrap();
            });
            let (job, operation) = got.recv().unwrap();
            let generation = format!("{}:0", operation.as_text());
            *jobs.0.lock().unwrap() = vec![smoozy_telegram::routing::gather::AJobAsHeld {
                job: job.as_text(),
                label: "Remote".into(),
                generation: generation.clone(),
                record_directory: true,
                rendering: Some(smoozy_telegram::routing::gather::TheProgress {
                    frame: 1,
                    of: 1,
                    percent: 0,
                }),
                waiting: None,
            }];
            let message = sim.a_message_from_the_bot("Remote preview");
            let subject = smoozy_telegram::actions::TheSubject {
                owning_machine: format!("machine-{name}"),
                job: Some(job.as_text()),
                hold: None,
                generation,
            };
            let server = format!("Server {}", name.to_uppercase());
            let button = (if owner_is_b { &b } else { &a })
                .the_job_messages()
                .a_stop_button(message, &subject, &server, "Remote")
                .unwrap();
            sim.the_user_taps(message, button["callback_data"].as_str().unwrap());
            rounds_until(40, &mut [&mut a, &mut b], &clock, &|_| {
                sim.said_to_the_user()
                    .iter()
                    .any(|text| text.contains("\nRemote\nStop this job?"))
            })
            .unwrap();
            assert!(
                !sim.said_to_the_user()
                    .iter()
                    .any(|text| text.ends_with("\nStop sent.")),
                "opening does not acknowledge a stop"
            );
            let question = *sim
                .state()
                .texts
                .iter()
                .find(|(_, text)| text.contains("\nRemote\nStop this job?"))
                .unwrap()
                .0;
            let store = (if owner_is_b { &b } else { &a }).the_job_messages().store;
            let confirm = store
                .the_action_contexts_bound_to(question)
                .unwrap()
                .into_iter()
                .find(|record| record.payload["confirmed"] == serde_json::json!(true))
                .unwrap();
            sim.the_user_taps(question, &confirm.token);
            rounds_until(40, &mut [&mut a, &mut b], &clock, &|_| {
                sim.said_to_the_user()
                    .iter()
                    .any(|text| text.ends_with("\nStop sent."))
            })
            .unwrap();
            for _ in 0..8 {
                a_round_of(&mut [&mut a, &mut b], &clock);
            }
            let (back, got) = std::sync::mpsc::channel();
            on.on_the_machine(move |machine| {
                back.send(the_stops_named_on(machine, &operation)).unwrap()
            });
            assert_eq!(
                got.recv().unwrap().len(),
                1,
                "the confirmed remote stop names one command"
            );
            assert_eq!(
                sim.said_to_the_user()
                    .iter()
                    .filter(|text| text.ends_with("\nStop sent."))
                    .count(),
                1
            );
        }

        #[test]
        fn a_restart_re_uses_the_board_and_machinery_identities() {
            let (sim, clock, [on_a, on_b], [a, b], _) = two_machines_settled();
            let (
                holder_name,
                mut holder,
                mut holders_supervisor,
                other_name,
                other,
                mut others_supervisor,
            ) = if a.is_holding() {
                ("a", a, on_a, "b", b, on_b)
            } else {
                ("b", b, on_b, "a", a, on_a)
            };
            let the_old_board = holders_supervisor
                .the_store()
                .board
                .expect("the holder recorded its board");
            let the_machinery_message = others_supervisor
                .the_store()
                .machinery_message
                .expect("the other recorded its machinery message");

            // The machine that was not holding: its supervisor starts again.
            let the_old_worker = other;
            let process = others_supervisor.starts_again();
            let again = format!("{other_name}-again");
            let (mut other, start) = a_worker_on(
                &others_supervisor,
                process,
                other_name,
                &again,
                &sim,
                &clock,
                JobsHeldHere::default(),
            );
            assert_eq!(
                start.state.machinery_message,
                Some(the_machinery_message),
                "the start carries it"
            );
            rounds_until(40, &mut [&mut holder, &mut other], &clock, &|_| {
                !sim.calls(&again, "pinChatMessage").is_empty()
            })
            .expect("the restarted worker spoke again");
            for _ in 0..10 {
                a_round_of(&mut [&mut holder, &mut other], &clock);
            }
            assert!(
                sim.calls(&again, "sendMessage").is_empty(),
                "no second machinery message: {:?}",
                sim.calls(&again, "sendMessage")
            );
            // **Since the map's piece 6 the restarted worker also edits its
            // status message** — its own recorded one, never a new one (the
            // status test below holds that); every other edit is the
            // machinery message's.
            let its_status_message = others_supervisor.the_store().status_message;
            assert!(sim
                .calls(&again, "editMessageText")
                .iter()
                .filter(|fields| fields["message_id"].as_i64() != its_status_message)
                .all(|fields| fields["message_id"] == serde_json::json!(the_machinery_message)));
            assert!(
                sim.calls(&again, "editMessageText")
                    .iter()
                    .any(|fields| fields["message_id"] == serde_json::json!(the_machinery_message)),
                "the recorded one was edited"
            );

            // The worker of the earlier run is refused at its next request.
            assert!(!the_old_worker.is_refused());
            assert!(
                the_old_worker
                    .the_job_messages()
                    .a_stop_button(
                        1,
                        &smoozy_telegram::actions::TheSubject {
                            owning_machine: format!("machine-{other_name}"),
                            job: Some("j".into()),
                            hold: None,
                            generation: "1".into(),
                        },
                        "S",
                        "J"
                    )
                    .is_none(),
                "no record is written for a worker of an earlier run"
            );
            assert!(the_old_worker.is_refused(), "and it knows to end itself");
            drop(the_old_worker);

            // The holder: its supervisor starts again, and its worker with it.
            drop(holder);
            let process = holders_supervisor.starts_again();
            let again = format!("{holder_name}-again");
            let (mut holder, start) = a_worker_on(
                &holders_supervisor,
                process,
                holder_name,
                &again,
                &sim,
                &clock,
                JobsHeldHere::default(),
            );
            assert_eq!(
                start.state.board,
                Some(the_old_board),
                "the start carries the board it created"
            );
            rounds_until(120, &mut [&mut holder, &mut other], &clock, &|_| {
                sim.the_board_on_top()
                    .is_some_and(|(top, _)| top != the_old_board)
            })
            .expect("a new board was confirmed after the holder's restart");
            for _ in 0..10 {
                a_round_of(&mut [&mut holder, &mut other], &clock);
            }
            assert!(
                !sim.state().pins.contains(&the_old_board),
                "`Telegram` B3: unpinned by its identity"
            );
            assert_eq!(sim.state().pins.len(), 1, "one pin, the new board");
            let (top, _) = sim.the_board_on_top().expect("pinned");
            let new_holders_store = if holder.is_holding() {
                holders_supervisor.the_store()
            } else {
                others_supervisor.the_store()
            };
            assert_eq!(
                new_holders_store.board,
                Some(top),
                "the new board written through its supervisor"
            );
        }

        /// **The Creator's fourteenth notes, note 2, through the whole program:
        /// a fresh server whose chat still has a deleted server's board pinned
        /// — its heartbeat never changing again — starts its Telegram worker
        /// and is given one one-frame job, to its finished message: one pin in
        /// all, its own board's** (`Telegram` B14: no announcement to a holder
        /// never seen alive; `Telegram` B3: the claimant lists itself; `Telegram` B16: the status
        /// message, the picture and the finished message are never pinned).
        /// Before, the announcement to the dead board was a second loud notice.
        #[test]
        fn the_fourteenth_notes_2_a_fresh_server_and_a_one_frame_job_cost_one_pin() {
            let (sim, clock) = (TheSim::default(), TheClock::default());
            let dead = smoozy_telegram::board::text::TheBoard {
                holder: "machine-gone".into(),
                heartbeat: "0123abcd".into(),
                heartbeat_moment: "18 Oct 2026, 09:00:00 UTC".into(),
                renewal_seconds: 60,
                route: smoozy_telegram::board::text::TheRouteMode::Asking,
                roster: vec![smoozy_telegram::board::roster::ARosterEntry {
                    colour: None,
                    machine: "machine-gone".into(),
                    display: "Server Gone".into(),
                }],
                instructions: Vec::new(),
            };
            let dead_board = sim.a_message_from_the_bot(&dead.compose().expect("composed"));
            sim.state().pins.push(dead_board);
            let on = ASupervisorOnAThreadOfItsOwn::started();
            let (mut worker, _) = a_worker_configured(
                &on,
                on.worker,
                "a",
                "a",
                &sim,
                &clock,
                JobsHeldHere::default(),
                Vec::new(),
                std::sync::Arc::new(std::time::SystemTime::now),
            );
            rounds_until(80, &mut [&mut worker], &clock, &|workers| {
                how_many_hold(workers) == 1
            })
            .expect("it holds");
            on.on_the_machine(|machine| {
                let (kitchen, operation) = a_render_running(machine, "Kitchen", vec![1], None);
                let directory = the_record_directory_of(machine, &kitchen);
                its_choice_is_everything(&directory);
                std::fs::write(format!("{directory}/preview-1.png"), a_png_of(1280, 720))
                    .expect("published");
                a_preview_journalled(machine, &kitchen, 1, true, 0);
                the_render_reports_its_ending(machine, &operation, asked::IT_FINISHED, None);
            });
            {
                let sim = sim.clone();
                rounds_until(30, &mut [&mut worker], &clock, &|_| {
                    sim.said_to_the_user()
                        .iter()
                        .any(|text| text.starts_with("Server A\nKitchen\nFinished."))
                })
                .expect("the finished message went");
            }
            // Three renewal intervals more, at rest.
            rounds(90, &mut worker, &clock);
            assert!(
                the_pictures_sent(&sim)
                    .iter()
                    .any(|caption| caption.contains("Kitchen \u{b7} Frame 1")),
                "the frame's picture went"
            );
            let pins = sim.calls("a", "pinChatMessage");
            let (top, board) = sim.the_board_on_top().expect("its board is on top");
            assert_eq!(pins.len(), 1, "one pin in all: {pins:?}");
            assert_eq!(
                pins[0]["message_id"],
                serde_json::json!(top),
                "its own board's"
            );
            assert_eq!(board.holder, "machine-a");
            assert!(
                board
                    .roster
                    .iter()
                    .any(|entry| entry.machine == "machine-a"),
                "the claimant lists itself"
            );
            assert!(
                !sim.state().pins.contains(&dead_board),
                "the dead board unpinned by its identity"
            );
            assert!(
                sim.calls("a", "sendMessage")
                    .iter()
                    .all(|fields| !fields["text"]
                        .as_str()
                        .is_some_and(|text| text.contains("smoozy-machinery"))),
                "no announcement"
            );
        }

        /// **`Telegram` section 19's one final board edit, marking this machine
        /// silent**, made by the holder when the polite stop arrives: the same
        /// board, edited once, with this machine off its roster — the heartbeat,
        /// the holder and the instructions as they were. A machine that is not
        /// holding has no board of its own to edit.
        #[test]
        fn the_holders_last_board_edit_takes_it_off_the_roster_and_changes_nothing_else() {
            use crate::the_telegram_worker::WhatTheLastEditCameTo;
            let (sim, _clock, _supervisors, [a, b], _) = two_machines_settled();
            let (holder, other, holders_machine) = if a.is_holding() {
                (&a, &b, "machine-a")
            } else {
                (&b, &a, "machine-b")
            };
            let (top, before) = sim.the_board_on_top().expect("pinned");
            assert!(before
                .roster
                .iter()
                .any(|entry| entry.machine == holders_machine));
            assert_eq!(
                other.a_last_board_edit_marking_this_machine_silent(),
                WhatTheLastEditCameTo::NotHolding
            );
            assert_eq!(
                holder.a_last_board_edit_marking_this_machine_silent(),
                WhatTheLastEditCameTo::Edited
            );
            let (still, after) = sim.the_board_on_top().expect("pinned");
            assert_eq!(still, top, "the same board, edited in place");
            assert!(
                !after
                    .roster
                    .iter()
                    .any(|entry| entry.machine == holders_machine),
                "off the roster"
            );
            assert_eq!(
                after.roster.len(),
                before.roster.len() - 1,
                "and nobody else taken off it"
            );
            assert_eq!(
                (
                    after.holder,
                    after.heartbeat,
                    after.heartbeat_moment,
                    after.instructions
                ),
                (
                    before.holder,
                    before.heartbeat,
                    before.heartbeat_moment,
                    before.instructions
                ),
                "nothing else changes, the heartbeat least of all"
            );
        }

        // --- the Telegram worker reads the journal and tells the phone about
        // jobs (the third piece of the Telegram worker's map, 2026-10-16) ---

        type TheSim = std::sync::Arc<crate::the_telegram_worker::a_simulated_conversation::Sim>;
        type TheClock =
            std::sync::Arc<crate::the_telegram_worker::a_simulated_conversation::TheTestsClock>;

        /// **One machine's worker over a real supervisor and a real journal in
        /// a package area of its own, settled**: it holds the slot, and its
        /// first turn took its cursor at the journal's end (piece 1's note).
        fn one_worker_reading_its_journal(
            reporting: Vec<(String, bool)>,
            the_machines_now: std::sync::Arc<dyn Fn() -> std::time::SystemTime + Send + Sync>,
        ) -> (
            TheSim,
            TheClock,
            ASupervisorOnAThreadOfItsOwn,
            crate::the_telegram_worker::TheAssembledWorker,
        ) {
            let sim = TheSim::default();
            let clock = TheClock::default();
            let on = ASupervisorOnAThreadOfItsOwn::started();
            let (mut worker, _) = a_worker_configured(
                &on,
                on.worker,
                "a",
                "a",
                &sim,
                &clock,
                JobsHeldHere::default(),
                reporting,
                the_machines_now,
            );
            rounds_until(80, &mut [&mut worker], &clock, &|workers| {
                how_many_hold(workers) == 1
            })
            .expect("the one machine holds the slot");
            assert!(
                on.the_store().journal_cursor.is_some(),
                "the first turn took its cursor"
            );
            (sim, clock, on, worker)
        }

        fn rounds(
            n: usize,
            worker: &mut crate::the_telegram_worker::TheAssembledWorker,
            clock: &TheClock,
        ) {
            for _ in 0..n {
                a_round_of(&mut [worker], clock);
            }
        }

        /// **A job's record directory with its manifest**, as the desktop
        /// publishes one (`Job files and outputs` M1): `frames` its range, in
        /// `group` where given, and no recorded reading, so the frame counts
        /// at its ending are the statement's own.
        fn a_record_directory_for(
            machine: &AStartOverAnAreaThatGoesWithIt,
            job: &Identity,
            frames: Vec<i64>,
            group: Option<&Identity>,
        ) -> String {
            let directory = machine.at.join("job-records").join(job.as_text());
            std::fs::create_dir_all(&directory).expect("the record directory is made");
            let mut manifest =
                smoozy_rendering_machine::composition::testing::a_manifest(job, "5.2", "Scene");
            manifest.frame_range =
                smoozy_job_files_machine::manifest::FrameRange::TheUsersParsedIntegers(frames);
            manifest.group = group.map(Identity::as_text);
            manifest.recorded_reading =
                smoozy_job_files_machine::manifest::TheRecordedReading::ThereIsNone;
            std::fs::write(
                directory.join(smoozy_job_files_machine::manifest::MANIFEST_FILE_NAME),
                manifest.as_written(),
            )
            .expect("the manifest is published");
            directory.display().to_string()
        }

        /// **A render running on the machine**: the job's record directory,
        /// its record and note (`Queue & History` Q3) and its operation record
        /// with one attempt's capture record, the sinks beside it.
        fn a_render_running(
            machine: &mut AStartOverAnAreaThatGoesWithIt,
            label: &str,
            frames: Vec<i64>,
            group: Option<&Identity>,
        ) -> (Identity, Identity) {
            a_render_running_as(machine, a_job(), label, frames, group)
        }

        fn a_render_running_as(
            machine: &mut AStartOverAnAreaThatGoesWithIt,
            job: Identity,
            label: &str,
            frames: Vec<i64>,
            group: Option<&Identity>,
        ) -> (Identity, Identity) {
            let directory = a_record_directory_for(machine, &job, frames, group);
            let operation = Identity::issue(IdentityKind::Operation).expect("randomness");
            let mut record = smoozy_state::machine_operations::OperationRecord::opened(
                operation.clone(),
                job.clone(),
                the_word_for(WorkerKind::Render),
            );
            record.the_kinds_safe_boundary_marker = Some(
                TheRenderKindsOwnField {
                    job: job.as_text(),
                    attempts: vec![OneAttemptsCapture {
                        attempt: 1,
                        ordinary_sink: format!("{directory}/ordinary"),
                        complaints_sink: format!("{directory}/complaints"),
                        available_bytes: 1,
                        render_process: None,
                        ending: None,
                        collection_incomplete_by_reconciliation: false,
                        the_termination_was_issued: false,
                        the_stops_on_it: Vec::new(),
                    }],
                }
                .as_written(),
            );
            machine
                .start
                .records
                .record_before_acting(&record)
                .expect("the record is written");
            let mut job_record = JobRecord::submitted(job.clone(), group.cloned(), directory, &[]);
            job_record.state = QueueState::Rendering {
                operation: operation.clone(),
            };
            the_job_record_and_its_note_in_one_act(
                &mut machine.start.queue,
                &mut machine.start.notes,
                &job_record,
                label,
            )
            .expect("the job is written");
            (job, operation)
        }

        /// **`Job files and outputs` C27's statement at an ending**: two files
        /// there and one not.
        fn two_there_and_one_not() -> TheStatementAtTheEnding {
            TheStatementAtTheEnding::It(
                smoozy_job_files_machine::reckoning::TheCompletenessStatement {
                    expected: 3,
                    present: vec![b"/out/1.png".to_vec(), b"/out/2.png".to_vec()],
                    absent: vec![b"/out/3.png".to_vec()],
                    present_at_zero_bytes: Vec::new(),
                    what_the_added_write_places_produced: Vec::new(),
                },
            )
        }

        /// **The worker's report of an ending, written as the supervisor writes
        /// it** (`Rendering` P1 step 9): the recorded outcome, the note's
        /// ending, the record ended, and the event journalled. `cause` is
        /// `Rendering` K14a's, on a failure.
        fn the_render_reports_its_ending(
            machine: &mut AStartOverAnAreaThatGoesWithIt,
            operation: &Identity,
            ending: &str,
            cause: Option<&str>,
        ) {
            use smoozy_runtime::capture::CollectionOutcome;
            let failed = ending != asked::IT_FINISHED;
            machine
                .start
                .a_render_attempt_ended(
                    operation,
                    crate::the_render_worker::TheEndingAsRecorded {
                        ending: ending.to_string(),
                        cause: cause.map(str::to_string),
                        reason: failed.then(|| "Blender exited with code 1".to_string()),
                        exit_status: Some(if failed { 1 } else { 0 }),
                        ordinary: Some(CollectionOutcome::Collected.in_words().to_string()),
                        complaints: Some(
                            CollectionOutcome::CollectedAndTheStreamWasEmpty
                                .in_words()
                                .to_string(),
                        ),
                        ordinary_retained: Some(12),
                        ordinary_discarded: Some(0),
                        ordinary_first_loss: None,
                        complaints_retained: Some(0),
                        complaints_discarded: Some(0),
                        complaints_first_loss: None,
                        marker_passed: Some(true),
                        something_followed_the_marker: Some(true),
                        device_line: None,
                        no_render_began: false,
                    },
                    None,
                    Some(two_there_and_one_not()),
                    WhatTheFigureIs::NoFrameCountsAsAlreadyThere,
                )
                .expect("the ending is written");
        }

        /// **An ending no worker reported** — given up by reconciliation, or
        /// left stopped — written through the job's own side of an ending, the
        /// one both routes end in.
        fn an_ending_no_worker_reported(
            machine: &mut AStartOverAnAreaThatGoesWithIt,
            job: &Identity,
            operation: &Identity,
            outcome: TheOutcomeAsWritten,
        ) {
            machine.start.the_jobs_side_of_an_ending(
                job,
                operation,
                TheEndingOnTheNote {
                    outcome,
                    exit_status: None,
                    the_attempt_whose_capture_record_holds_the_words: 1,
                    the_reason_the_machine_recorded: None,
                    no_render_began: false,
                    the_device_line_as_observed: None,
                },
                WhatTheFigureIs::NoFrameCountsAsAlreadyThere,
                two_there_and_one_not(),
                TheFreeSpaceAtTheEnding::NoneWasTaken {
                    why: "a test".to_string(),
                },
            );
        }

        /// The buttons the last edit of a message attached, by their labels.
        fn the_buttons_on(
            sim: &crate::the_telegram_worker::a_simulated_conversation::Sim,
            message_text: &str,
        ) -> Vec<String> {
            sim.calls("a", "editMessageText")
                .into_iter()
                .chain(sim.calls("a", "editMessageReplyMarkup"))
                .filter(|fields| {
                    fields["text"]
                        .as_str()
                        .is_none_or(|text| text == message_text)
                })
                .filter_map(|fields| {
                    fields["reply_markup"]["inline_keyboard"]
                        .as_array()
                        .cloned()
                })
                .last()
                .unwrap_or_default()
                .iter()
                .filter_map(|row| row[0]["text"].as_str().map(str::to_string))
                .collect()
        }

        fn said_once(said: &[String], beginning: &str) -> String {
            let found: Vec<&String> = said
                .iter()
                .filter(|text| text.starts_with(beginning))
                .collect();
            assert_eq!(found.len(), 1, "said once: {beginning:?} in {said:#?}");
            found[0].clone()
        }

        /// **The map's piece 3: each ending sends its one message** — a finish
        /// (`Telegram` E1), a failure of the machine's own cause with *try it
        /// again* and the words button (`Telegram` E3, `Telegram` Y4a), a failure of the
        /// file's own with no *try it again* and the sentence that says so, a
        /// job given up (`Telegram` E1), and a stop's recorded outcome with its
        /// counts (`Telegram` D2) — **each once, however many turns follow**.
        ///
        /// **Before this piece nothing read the journal**, and none of the five
        /// was said.
        #[test]
        fn each_ending_the_journal_carries_sends_its_one_message() {
            use smoozy_telegram::job_messages::{IT_NEEDS_A_CHANGE, SMOOZY_CANNOT_TELL_WHY};
            let (sim, clock, on, mut worker) = one_worker_reading_its_journal(
                Vec::new(),
                std::sync::Arc::new(std::time::SystemTime::now),
            );
            on.on_the_machine(|machine| {
                let (_, finished) = a_render_running(machine, "Kitchen", vec![1, 2, 3], None);
                the_render_reports_its_ending(machine, &finished, asked::IT_FINISHED, None);
                let (_, machines) = a_render_running(machine, "Hall", vec![1, 2, 3], None);
                the_render_reports_its_ending(
                    machine,
                    &machines,
                    asked::IT_FAILED,
                    Some(crate::the_render_worker::THE_MACHINES_OWN),
                );
                let (_, files) = a_render_running(machine, "Porch", vec![1, 2, 3], None);
                the_render_reports_its_ending(
                    machine,
                    &files,
                    asked::IT_FAILED,
                    Some(crate::the_render_worker::THE_FILES_OWN),
                );
                let (given_up, its) = a_render_running(machine, "Attic", vec![1, 2, 3], None);
                an_ending_no_worker_reported(
                    machine,
                    &given_up,
                    &its,
                    TheOutcomeAsWritten::GivenUp,
                );
                let (stopped, its) = a_render_running(machine, "Cellar", vec![1, 2, 3], None);
                an_ending_no_worker_reported(
                    machine,
                    &stopped,
                    &its,
                    TheOutcomeAsWritten::LeftStopped,
                );
            });
            rounds(6, &mut worker, &clock);
            let said = sim.said_to_the_user();
            // **No length**: the note holds no start, since no attempt was
            // started here, and a length is never made up.
            assert_eq!(
                said_once(&said, "Server A\nKitchen\nFinished."),
                "Server A\nKitchen\nFinished. 2 of 3 files written."
            );
            let machines = said_once(&said, "Server A\nHall\n🔴 Failed");
            assert!(
                machines.contains("Blender exited with code 1."),
                "{machines}"
            );
            assert!(machines.contains("2 frames on the server."), "{machines}");
            assert!(
                !machines.contains(IT_NEEDS_A_CHANGE) && !machines.contains(SMOOZY_CANNOT_TELL_WHY),
                "{machines}"
            );
            assert_eq!(
                the_buttons_on(&sim, &machines),
                [
                    "Send Output log",
                    "Retry"
                ],
                "`Telegram` Y4a: *try it again* on the machine's own cause; no Stop on an ending (`Telegram` C1b)"
            );
            let files = said_once(&said, "Server A\nPorch\n🔴 Failed");
            assert!(files.ends_with(IT_NEEDS_A_CHANGE), "{files}");
            assert_eq!(
                the_buttons_on(&sim, &files),
                ["Send Output log"],
                "no *try it again*, and no Stop on an ending (`Telegram` C1b)"
            );
            said_once(
                &said,
                "Server A\nAttic\nAbandoned. Interrupted twice.",
            );
            assert_eq!(
                said_once(&said, "Server A\nCellar\nStopped."),
                "Server A\nCellar\nStopped. 2 frames on the server; 1 frame not rendered."
            );
            assert_eq!(
                said.len(),
                5,
                "one message each and nothing else: {said:#?}"
            );
            let cursor = on.the_store().journal_cursor.expect("held");
            rounds(6, &mut worker, &clock);
            assert_eq!(sim.said_to_the_user(), said, "never twice");
            assert!(
                on.the_store().journal_cursor.expect("held") >= cursor,
                "the cursor moved past the work"
            );
        }

        /// A stopped two-layer job with a statement too large for its report
        /// still tells the true frame count, rather than mistaking absence for zero.
        #[test]
        fn a_stopped_multi_layer_job_keeps_its_counts_when_the_statement_outgrows_a_report() {
            use crate::the_render_worker::TheEnding;
            use smoozy_job_files_machine::manifest::FrameRange;
            use smoozy_job_files_machine::reckoning::{
                the_completeness_statement, AWalkEntry, WhatKindOfEntry,
            };
            let (sim, clock, on, mut worker) = one_worker_reading_its_journal(
                Vec::new(),
                std::sync::Arc::new(std::time::SystemTime::now),
            );
            on.on_the_machine(|machine| {
                let (job, operation) = a_render_running(machine, "Two layers", (1..=2000).collect(), None);
                let directory = machine.start.queue.one_record(&job).unwrap().record_directory;
                let at = format!("{directory}/{}", smoozy_job_files_machine::manifest::MANIFEST_FILE_NAME);
                let mut manifest = smoozy_job_files_machine::manifest::SubmissionManifest::read_back(&std::fs::read(&at).unwrap()).unwrap();
                let folder = manifest.job_output_folder.the_path_it_names().unwrap().to_string();
                let mut printed: serde_json::Value = serde_json::from_str(include_str!("../../Job files and outputs — machine/tests/the_curly_brace_stand_in_as_blender_5_3_printed_it.json")).unwrap();
                let first = printed["outputs"]["per_frame"][0].clone();
                printed["outputs"]["per_frame"] = serde_json::Value::Array((1..=2000).map(|frame| {
                    let mut one = first.clone();
                    one["frame"] = serde_json::json!(frame);
                    one["the_regular_output_paths_answered_path"] = serde_json::json!(format!("/out/_preview{frame:04}.png").into_bytes());
                    one
                }).collect());
                printed["settings"]["scenes"][0]["frame_end"] = serde_json::json!(2000);
                printed["settings"]["scenes"][0]["frame_count"] = serde_json::json!(2000);
                let mut stream = smoozy_job_files_machine::reading::THE_OPENING_SENTINEL.to_vec();
                stream.extend(serde_json::to_vec(&printed).unwrap());
                stream.extend_from_slice(smoozy_job_files_machine::reading::THE_CLOSING_SENTINEL);
                let composed = smoozy_job_files_machine::composing::the_reading_and_everything_derived_from(
                    smoozy_job_files_machine::reading_script::the_printed_reading_in(&stream).unwrap(),
                    smoozy_job_files_machine::composing::WhatTheReadingIsComposedAgainst {
                        the_folder_the_blend_sits_in: b"/home/ubuntu/rendering",
                        job_output_folder: &folder,
                        enters_at: &smoozy_job_files_machine::main_output::WhereTheRenderEnters {
                            scene: smoozy_job_files_machine::reading::ArtistsText::of(b"Scene".to_vec()),
                            view_layer: smoozy_job_files_machine::reading::ArtistsText::of(b"a".to_vec()),
                        },
                        the_jobs_pins: &[],
                    },
                ).unwrap();
                let smoozy_job_files_machine::inventory::WhatTheInventoryIs::It(inventory) = &composed.inventory else { panic!("inventory"); };
                let walk: Vec<AWalkEntry> = inventory.entries.iter().filter(|entry| entry.frame.is_some_and(|f| f <= 832)).map(|entry| AWalkEntry {
                    path_under_the_job_output_folder: entry.predicted_path.strip_prefix(format!("{folder}/").as_bytes()).unwrap().to_vec(),
                    kind: WhatKindOfEntry::AFile, size: 1,
                }).collect();
                let statement = the_completeness_statement(inventory, &walk, &folder);
                assert!(serde_json::to_vec(&statement).unwrap().len() > crate::the_render_worker::THE_LONGEST_STATEMENT_ONE_REPORT_CARRIES);
                // Actual render-start reading, including the file's own range.
                manifest.frame_range = FrameRange::TheFilesOwn;
                std::fs::write(&at, manifest.as_written()).unwrap();
                std::fs::write(std::path::Path::new(&directory).join(smoozy_job_files_machine::manifest::the_recorded_readings_file_name(1)), serde_json::to_vec(&composed).unwrap()).unwrap();
                let ending = TheEnding {
                    outcome: smoozy_rendering_machine::endings::RecordedOutcome::Finished,
                    hold: None, exit_status: Some(0), streams: None,
                    statement: Some(Ok(statement)), figure: WhatTheFigureIs::It(832), the_device_line: None,
                };
                // A real stop's two recorded facts: requested, interrupt issued.
                let WhatTheMachineHoldsUnderAnIdentity::AnOperationRecord(mut held) = machine.start.records.what_is_held_under(&operation).unwrap() else { panic!("operation"); };
                held.the_stop_was_asked_for().unwrap();
                let mut field = TheRenderKindsOwnField::read_back(held.the_kinds_safe_boundary_marker.as_deref().unwrap()).unwrap();
                field.attempts[0].the_termination_was_issued = true;
                held.the_kinds_safe_boundary_marker = Some(field.as_written());
                machine.start.records.write_it_back(&held).unwrap();
                let fields = ending.as_fields_for(
                    Fields::none().and(THE_RUN_THE_WORKER_WAS_STARTED_UNDER, machine.start.run.run.as_text()), &directory, 1,
                ).unwrap();
                assert!(fields.value(THE_COMPLETENESS_STATEMENT_FIELD).is_none(), "the report stays small");
                let request = Request::speaking(THE_PROTOCOL_VERSION_THIS_BUILD_SPEAKS, operation, THE_WORKERS_REPORT_REQUEST).carrying(fields);
                let reported = answer(&request, &mut machine.start);
                assert_eq!(reported.fields.text(WHETHER_THE_REPORT_WAS_ACCEPTED), Some(IT_WAS_ACCEPTED));
                let note = machine.start.notes.read(&job).unwrap().unwrap();
                assert_eq!(note.ending.unwrap().outcome, TheOutcomeAsWritten::LeftStopped);
                assert!(matches!(note.the_completeness_statement, Some(TheStatementAtTheEnding::It(_))));
            });
            rounds(6, &mut worker, &clock);
            assert_eq!(said_once(&sim.said_to_the_user(), "Server A\nTwo layers\nStopped."), "Server A\nTwo layers\nStopped. 832 frames on the server; 1,168 frames not rendered.");
        }

        /// **The Creator's thirteenth notes, notes 5, 9 and 10: a job whose File
