        #[test]
        fn twentieth_off_on_either_first_frame_job_silences_the_question_and_durable_drop() {
            for silent_first in [false, true] {
                let (sim, clock, on, mut worker) = one_worker_reading_its_line();
                let (send, receive) = std::sync::mpsc::channel();
                on.on_the_machine(move |machine| {
                    let (first, operation) =
                        a_render_running(machine, "Silent check", vec![1], None);
                    let (held, hold) = a_hold_placed_on(
                        machine,
                        "Silent range",
                        (1..=20).collect(),
                        Some(&first),
                        "the first-frame check",
                    );
                    its_choice_is_everything(&the_record_directory_of(machine, &first));
                    its_choice_is_everything(&the_record_directory_of(machine, &held));
                    let silent = if silent_first { &first } else { &held };
                    twentieth_choice(&the_record_directory_of(machine, silent), "Nothing");
                    a_frame_produced_with_its_layers(
                        machine,
                        &first,
                        1,
                        &[("Interior", 0), ("Reflection", 1)],
                    );
                    the_render_reports_its_ending(machine, &operation, asked::IT_FINISHED, None);
                    send.send((first, operation, held, hold)).unwrap();
                });
                let (_first, _operation, held, hold) = receive.recv().unwrap();
                rounds(8, &mut worker, &clock);
                assert!(
                    sim.said_to_the_user().is_empty(),
                    "{silent_first}: {:?}",
                    sim.said_to_the_user()
                );
                assert!(the_albums_sent(&sim).is_empty());
                assert!(sim.calls("a", "sendPhoto").is_empty());
                let check = held.clone();
                let hold_check = hold.clone();
                on.on_the_machine(move |machine| {
                    assert!(matches!(
                        machine.start.queue.one_record(&check).unwrap().state,
                        QueueState::Held { .. }
                    ));
                    assert!(machine
                        .start
                        .holds
                        .read(&hold_check)
                        .unwrap()
                        .unwrap()
                        .release
                        .is_none());
                });
                let answer_hold = hold.clone();
                on.on_the_machine(move |machine| {
                    answer(
                        &an_answer_to(&answer_hold, THE_ANSWER_IS_YES, THE_ROUTE_IS_THE_DESK),
                        &mut machine.start,
                    );
                });
                rounds(8, &mut worker, &clock);
                assert!(
                    sim.said_to_the_user().is_empty(),
                    "a desk answer was reported: {:?}",
                    sim.said_to_the_user()
                );
                drop(worker);
                on.on_the_machine(move |machine| {
                    let (first, operation) =
                        a_render_running(machine, "Silent dropped check", vec![1], None);
                    let (held, _) = a_hold_placed_on(
                        machine,
                        "Silent dropped range",
                        (1..=20).collect(),
                        Some(&first),
                        "the first-frame check",
                    );
                    its_choice_is_everything(&the_record_directory_of(machine, &first));
                    its_choice_is_everything(&the_record_directory_of(machine, &held));
                    let silent = if silent_first { &first } else { &held };
                    twentieth_choice(&the_record_directory_of(machine, silent), "Nothing");
                    // Drops remove the held job's records before the new worker reads.
                    an_ending_with_no_frame(
                        machine,
                        &first,
                        &operation,
                        TheOutcomeAsWritten::LeftStopped,
                    );
                    let (first, _) =
                        a_render_running(machine, "Silent cancelled check", vec![1], None);
                    let (held, _) = a_hold_placed_on(
                        machine,
                        "Silent cancelled range",
                        (1..=20).collect(),
                        Some(&first),
                        "the first-frame check",
                    );
                    its_choice_is_everything(&the_record_directory_of(machine, &first));
                    its_choice_is_everything(&the_record_directory_of(machine, &held));
                    let silent = if silent_first { &first } else { &held };
                    twentieth_choice(&the_record_directory_of(machine, silent), "Nothing");
                    let mut waiting = machine.start.queue.one_record(&first).unwrap();
                    waiting.state = QueueState::Waiting;
                    machine.start.queue.write(&waiting).unwrap();
                    // These journal fixtures publish in the package area's
                    // own scratch directory, rather than a configured root.
                    let material = Ok(WhereTheMaterialSits {
                        job_record_directory: the_record_directory_of(machine, &first).into(),
                        remap_material: machine.at.join("unused-remap"),
                        per_job_note: machine.start.notes.where_one_sits(&first),
                        job_output_folder: None,
                        reporting_choice_now: None,
                    });
                    machine.start.queue.remove(&first).unwrap();
                    machine
                        .start
                        .after_a_removal(&first, material, None, asked::IT_WAS_REMOVED);
                    machine.start.the_holds_on_what_was_removed(vec![first]);
                    assert!(machine.start.queue.one_record(&held).is_none());
                });
                let mut again = a_worker_reading_its_line(&on, on.worker, &sim, &clock);
                rounds(12, &mut again, &clock);
                assert!(
                    sim.said_to_the_user().is_empty(),
                    "a silent check spoke after restart: {:?}",
                    sim.said_to_the_user()
                );
                assert!(!sim
                    .said_to_the_user()
                    .iter()
                    .any(|text| text.contains("Needs your answer")));
            }
        }

        #[test]
        fn twentieth_off_hides_the_automatic_status_but_answers_status_and_frame() {
            let (sim, clock, on, mut worker) = one_worker_reading_its_line();
            on.on_the_machine(|machine| {
                let (job, _) = a_render_running(machine, "Silent active", vec![1, 2], None);
                twentieth_choice(&the_record_directory_of(machine, &job), "Nothing");
                a_frame_produced_with_its_layers(
                    machine,
                    &job,
                    1,
                    &[("Interior", 0), ("Reflection", 1)],
                );
                machine
                    .start
                    .journal_about(
                        asked::THE_RENDER_ATTEMPT_STARTED_EVENT,
                        Some(job),
                        "attempt 1",
                    )
                    .unwrap();
            });
            let before = sim.status_calls("a").len();
            rounds(12, &mut worker, &clock);
            assert!(sim.said_to_the_user().is_empty());
            assert!(the_albums_sent(&sim).is_empty());
            let calls = sim.status_calls("a");
            assert!(calls.len() > before);
            for (_, fields) in &calls[before..] {
                let text = fields["text"].as_str().unwrap();
                assert!(
                    !text.contains("Silent active")
                        && !text.contains("Idle")
                        && !text.contains("frame"),
                    "{text}"
                );
                assert!(
                    fields.get("reply_markup").is_none()
                        || fields["reply_markup"]["inline_keyboard"]
                            .as_array()
                            .is_some_and(Vec::is_empty),
                    "{fields}"
                );
            }
            sim.the_user_says("status");
            rounds(20, &mut worker, &clock);
            assert!(
                sim.said_to_the_user()
                    .iter()
                    .any(|text| text.contains("Silent active")),
                "typed status omitted the job: {:?}",
                sim.said_to_the_user()
            );
            sim.the_user_says("frame 1");
            rounds(20, &mut worker, &clock);
            assert_eq!(
                the_albums_sent(&sim).len(),
                1,
                "the typed frame request is answered"
            );
            let album = &the_albums_sent(&sim)[0];
            assert!(album[0].contains("Silent active"));
            assert!(album.iter().skip(1).all(|text| text.starts_with("Frame 1 ·")));
        }

