        /// **`Telegram` M2: a finished job's contact sheet** — at most ten of
        /// its main copies, as one album, its caption on the first picture —
        /// and no Blender runs.
        #[test]
        fn a_contact_sheet_of_at_most_ten_at_the_end() {
            let (sim, clock, on, mut worker) = one_worker_reading_its_journal(
                Vec::new(),
                std::sync::Arc::new(std::time::SystemTime::now),
            );
            on.on_the_machine(|machine| {
                let (kitchen, operation) =
                    a_render_running(machine, "Kitchen", (1..=12).collect(), None);
                let directory = the_record_directory_of(machine, &kitchen);
                its_choice_is_everything(&directory);
                for frame in 1..=12 {
                    std::fs::write(
                        format!("{directory}/preview-{frame}.png"),
                        a_png_of(1280, 720),
                    )
                    .expect("published");
                }
                the_render_reports_its_ending(machine, &operation, asked::IT_FINISHED, None);
            });
            rounds(6, &mut worker, &clock);
            let albums = sim.calls("a", "sendMediaGroup");
            assert_eq!(albums.len(), 1, "one album at the job's end");
            let media = albums[0]["media"]
                .as_array()
                .cloned()
                .expect("an album carries its pictures");
            assert_eq!(media.len(), 10, "at most ten");
            assert_eq!(
                media[0]["caption"],
                "Server A\nKitchen \u{b7} 10 of 12 frames, evenly spread"
            );
            assert!(
                media[1..].iter().all(|one| one.get("caption").is_none()),
                "the caption on the first alone"
            );
            rounds(6, &mut worker, &clock);
            assert_eq!(sim.calls("a", "sendMediaGroup").len(), 1, "never twice");
        }

        /// **The contact sheets sent**, album by album in the order sent, each
