        /// **`Server Setup` B7a: a 4.2 build holds for a person, publishes
        /// nothing, and installs only on *Install anyway* — still as *your
        /// build*.**
        #[test]
        fn a_users_build_below_four_five_holds_and_installs_only_on_install_anyway() {
            let mut machine = a_machine_a_placement_wrote();
            let (run, area) = a_users_build_waiting_in_staging(&mut machine, "4.2.0", "anyway");
            let line = ALineNobodyMayAsk(std::cell::Cell::new(0));
            one_step_driven(
                &mut machine,
                &run,
                asked::THE_UNPACK_STEP,
                vec![(asked::THE_USERS_OWN_ARCHIVE_FIELD, THE_USERS_ARCHIVE)],
                &line,
            );
            let held = one_step_driven(
                &mut machine,
                &run,
                asked::THE_BUILD_IS_PUBLISHED_STEP,
                vec![],
                &line,
            );
            assert!(
                held.held_for_a_person && !held.it_ran_to_its_end,
                "{held:?}"
            );
            assert!(
                what_the_blender_area_holds(&area).is_empty(),
                "a held build was published"
            );
            assert!(
                machine.start.the_setup_run_this_supervisor_opened.is_some(),
                "a hold ended the run"
            );
            let state = the_runs_state(&mut machine, &run);
            assert_eq!(
                state.text(asked::THE_QUESTION_STANDS_AT_VERSION_FIELD),
                Some("4.2.0")
            );
            assert_eq!(state.text(asked::THE_RUNS_ENDING_FIELD), None);
            assert_eq!(state.text(asked::THE_INSTALL_ROUTE_FIELD), None);

            let installed = one_step_driven(
                &mut machine,
                &run,
                asked::THE_BUILD_IS_PUBLISHED_STEP,
                vec![(asked::THE_USERS_ANSWER_FIELD, asked::INSTALL_ANYWAY)],
                &line,
            );
            assert!(installed.it_ran_to_its_end, "{installed:?}");
            let holds = what_the_blender_area_holds(&area);
            assert!(
                holds.len() == 1 && holds[0].starts_with("blender-4.2.0-"),
                "the Blender area holds {holds:?}"
            );
            let state = the_runs_state(&mut machine, &run);
            assert_eq!(
                state.text(asked::THE_QUESTION_STANDS_AT_VERSION_FIELD),
                None
            );
            assert_eq!(
                state.text(asked::THE_INSTALL_ROUTE_FIELD),
                Some(asked::YOUR_BUILD)
            );
            assert_eq!(line.0.get(), 0, "the line was asked");
            std::fs::remove_dir_all(&area).ok();
        }

        /// **`Server Setup` B7a: a decline discards the staged build, publishes
        /// nothing, strikes the publication from the run's list and records the
        /// discard in its place — and the run goes on.**
        #[test]
        fn a_declined_users_build_is_discarded_and_the_record_says_so() {
            let mut machine = a_machine_a_placement_wrote();
            let (run, area) = a_users_build_waiting_in_staging(&mut machine, "4.2.0", "declined");
            let line = ALineNobodyMayAsk(std::cell::Cell::new(0));
            one_step_driven(
                &mut machine,
                &run,
                asked::THE_UNPACK_STEP,
                vec![(asked::THE_USERS_OWN_ARCHIVE_FIELD, THE_USERS_ARCHIVE)],
                &line,
            );
            one_step_driven(
                &mut machine,
                &run,
                asked::THE_BUILD_IS_PUBLISHED_STEP,
                vec![],
                &line,
            );
            let declined = one_step_driven(
                &mut machine,
                &run,
                asked::THE_BUILD_IS_PUBLISHED_STEP,
                vec![(asked::THE_USERS_ANSWER_FIELD, asked::THE_USER_DECLINED)],
                &line,
            );
            assert!(
                declined.it_ran_to_its_end && declined.the_boundary.is_none(),
                "{declined:?}"
            );
            assert!(
                what_the_blender_area_holds(&area).is_empty(),
                "a declined build was published"
            );
            let staging: Vec<_> = std::fs::read_dir(area.join("staging"))
                .expect("the staging area is there")
                .filter_map(|entry| entry.ok())
                .collect();
            assert!(staging.is_empty(), "the staged build was not discarded");
            let state = the_runs_state(&mut machine, &run);
            assert!(
                state.text(asked::THE_DISCARD_FIELD).is_some(),
                "no discard recorded"
            );
            assert_eq!(
                state.text(asked::THE_QUESTION_STANDS_AT_VERSION_FIELD),
                None
            );
            assert_eq!(state.text(asked::THE_INSTALL_ROUTE_FIELD), None);
            assert_eq!(
                state.text(asked::THE_RUNS_ENDING_FIELD),
                None,
                "the decline ended the run"
            );
            let open = machine
                .start
                .the_setup_run_this_supervisor_opened
                .as_ref()
                .expect("the run goes on");
            assert!(
                !open.composed.contains(&Boundary::Blender),
                "the publication was not struck from the composed list"
            );
            assert_eq!(line.0.get(), 0, "the line was asked");
            std::fs::remove_dir_all(&area).ok();
        }

