        /// **The worker's own question, asked the way the worker asks it.**
        fn what_the_worker_is_told(
            machine: &mut AStartOverAnAreaThatGoesWithIt,
        ) -> crate::the_setup_worker::WhatThereIsToDo {
            let asked_for_work = answer(
                &asking(
                    crate::the_setup_worker::THE_SETUP_WORKERS_OWN_WORK_REQUEST,
                    Fields::none().and(
                        crate::the_setup_worker::THE_SETUP_WORKERS_OWN_PROCESS_FIELD,
                        std::process::id().to_string(),
                    ),
                ),
                &mut machine.start,
            );
            crate::the_setup_worker::what_there_is_to_do_in(&asked_for_work.fields)
                .expect("the answer reads back")
        }

        /// **`Server Setup` B7a: while the question stands, the worker is told a
        /// person is being asked, and that wait never runs out** — a person may
        /// take longer than the worker's half-hour idle bound over *Install
        /// anyway*. Once answered, a plain *nothing yet* counts again.
        #[test]
        fn a_held_users_build_tells_its_worker_a_person_is_asked_and_the_worker_waits_past_its_idle_bound(
        ) {
            use crate::the_setup_worker::{
                it_stops_for_want_of_work, WhatThereIsToDo,
                HOW_LONG_A_WORKER_WAITS_WITH_NOTHING_TO_DO,
            };
            let mut machine = a_machine_a_placement_wrote();
            let (run, area) = a_users_build_waiting_in_staging(&mut machine, "4.2.0", "waits");
            let line = ALineNobodyMayAsk(std::cell::Cell::new(0));
            one_step_driven(
                &mut machine,
                &run,
                asked::THE_UNPACK_STEP,
                vec![(asked::THE_USERS_OWN_ARCHIVE_FIELD, THE_USERS_ARCHIVE)],
                &line,
            );
            let held = one_step_driven(
                &mut machine,
                &run,
                asked::THE_BUILD_IS_PUBLISHED_STEP,
                vec![],
                &line,
            );
            assert!(held.held_for_a_person, "{held:?}");

            let past_the_bound =
                HOW_LONG_A_WORKER_WAITS_WITH_NOTHING_TO_DO + std::time::Duration::from_secs(60);
            let told = what_the_worker_is_told(&mut machine);
            assert_eq!(told, WhatThereIsToDo::NothingWhileAPersonIsAsked);
            assert!(
                !it_stops_for_want_of_work(&told, past_the_bound),
                "the worker gave up on a run held for a person"
            );

            let installed = one_step_driven(
                &mut machine,
                &run,
                asked::THE_BUILD_IS_PUBLISHED_STEP,
                vec![(asked::THE_USERS_ANSWER_FIELD, asked::INSTALL_ANYWAY)],
                &line,
            );
            assert!(installed.it_ran_to_its_end, "{installed:?}");
            let told = what_the_worker_is_told(&mut machine);
            assert_eq!(
                told,
                WhatThereIsToDo::NothingYet,
                "the answered question still holds the worker"
            );
            assert!(
                it_stops_for_want_of_work(&told, past_the_bound),
                "the idle bound no longer holds"
            );
            std::fs::remove_dir_all(&area).ok();
        }

